insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 1, 'The Ekene 2027 cash call ledger (synthetic) states a reconciliation lag of 2 months, the negative call rule "carry" and no cash call below 500000.000000. January 2027 is forecast at 4000000.000000 and spends 3600000.000000, an over-call of 400000.000000. Which call does the engine credit it against?', '["The February 2027 call, the very next request, where each party''s January difference comes off before any lag is counted", "The January 2027 call itself, reissued once the actuals are known so that each party pays exactly its actual share", "The March 2027 call, two months later, where EKO is called 5800000.000000 on a forecast share of 6000000.000000", "One reconciliation at the close of 2027 for all twelve months"]'::jsonb, 2, 'The engine''s reason reads "2027-03: the over-call of 400000 in 2027-01 (forecast 4000000, actual 3600000) is credited against this cash call, 2 months later", and EKO''s March adjustment of 200000.000000 takes its call to 5800000.000000. The lag is a stated term, so the next request (February) is only reached when the contract states a lag of 1. No call is reissued, and nothing waits for a year end: each difference meets the call the lag names.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 2, 'A learner copies the Ekene 2027 ledger into the recovery calculator and types 0 into the reconciliation lag control, so that each month''s difference would settle against its own call. What does the engine return?', '["A refusal, in the engine''s own words: reconciliationLagMonths must be an integer at or above 1; got 0", "A ledger in which every month is called at its actual spend, so each difference is 0.000000 and every balance closes at 0.000000", "The same ledger run with a lag of 1, the smallest lag the engine accepts, substituted for the 0 and reported in the basis", "A ledger that states each month''s difference and adjusts no later call with it, leaving all of them open at the close"]'::jsonb, 0, 'The engine refuses the lag by name: "reconciliationLagMonths must be an integer at or above 1; got 0". A month cannot adjust its own call, because its actual is known only after the call is made. The engine substitutes no lag of its own: the lag is a stated input with no default, and a call without one is refused with the same message ending "got nothing".'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 3, 'The golden input cc-ekene-2027-lag1 runs the same twelve Ekene months with a lag of 1 month, the rule "carry" and no cash call below 500000.000000. What do the calls over the year total?', '["68604000.000000, the yearly calls of the Ekene ledger as the fixture states it, which the lag cannot move", "69148000.000000, the year''s actual spend, since a lag of 1 settles every month''s difference inside the year", "69052000.000000, the calls of a ledger in which every month is called whatever its forecast", "68500000.000000"]'::jsonb, 3, 'The engine returns calls of 68500000.000000 over the year with a lag of 1, against 68604000.000000 with the fixture''s lag of 2. Both ledgers bill 448000.000000 in arrears and both spend 69148000.000000; the lag moves the month in which a difference is settled, so what is still open at the close differs. 69052000.000000 belongs to the golden input with no threshold, cc-ekene-2027-every-month.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 4, 'On the golden input cc-ekene-2027-lag1 (a lag of 1 month, the rule "carry", no cash call below 500000.000000), November 2027 is forecast at 7000000.000000 and spends 6896000.000000. Where does the engine put that over-call of 104000?', '["Into January 2028, outside the ledger, left open at the close", "Against the December 2027 call, one month later, in the engine''s own reason", "Written off to the operator at the year end", "Refunded as a negative call in November itself"]'::jsonb, 1, 'The lag-1 reasons include "2027-12: the over-call of 104000 in 2027-11 (forecast 7000000, actual 6896000) is credited against this cash call, 1 month later". A lag of 2 would carry it past December and leave it among the differences not yet adjusted. Nothing is written off in a cash call ledger, and the stated rule is "carry", which never turns a difference into a negative call in its own month.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 5, 'On the Ekene 2027 ledger (lag 2 months, rule "carry", no call below 500000.000000), February''s under-call of 500000 comes due in April, and April has a forecast of 0.000000. What does the engine record for EKO in April 2027?', '["A call of 250000.000000 in April for the under-call alone", "Nothing: February''s under-call is dropped", "Arrears of 250000.000000 billed in May, since an under-call that meets a month with no call is billed like spend", "A call of 0.000000, an adjustment of -250000.000000 and -250000.000000 carried, so that April makes no call"]'::jsonb, 3, 'April''s forecast of 0 is below the stated threshold, so the month makes no call; the engine''s reason reads "2027-04: the under-call of 500000 in 2027-02 (forecast 6000000, actual 6500000) is added to the next cash call (none is made this month), 2 months later", and EKO''s April row shows the adjustment and the amount carried at -250000.000000. A zero-forecast month is called for its adjustment only when no threshold is stated. Arrears billing is for actual spend made without a call.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 6, 'May 2027 is forecast at 400000.000000, below the Ekene threshold of 500000.000000 (lag 2, rule "carry"), and spends 448000.000000 with no call made. What does EKO pay in June?', '["4574000.000000: its call of 4350000.000000 and an arrears billing of 224000.000000", "4350000.000000, its June call, with May''s spend left in its balance until the next called month clears it", "4500000.000000, its forecast share for June, since the arrears and the credit held from May net out", "9148000.000000, what the whole venture pays in June, calls and arrears together"]'::jsonb, 0, 'The engine''s June row for EKO shows a call of 4350000.000000, an arrears billing of 224000.000000 and a payment of 4574000.000000; its reason reads "2027-06: the actual of 2027-05, 448000, made without a cash call, is billed in arrears". What a party pays in a month is its call plus its arrears billing. 9148000.000000 is June''s total across the parties.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 7, 'An over-call of 1200000 from July 2027 meets September, a month forecast at only 1000000.000000, on the Ekene ledger (lag 2 months, rule "carry", no call below 500000.000000). What does EKO get in September?', '["A negative call of -100000.000000, the excess over its forecast share paid back in September", "A call of 500000.000000, with the whole adjustment of 600000.000000 moved to October", "A call of 0.000000 on a forecast share of 500000.000000, and 100000.000000 carried to the next call", "A call of 0.000000, with the 100000.000000 excess written off to the operator, since the engine lets no call go below 0.000000"]'::jsonb, 2, 'The fixture states "carry", and the engine''s basis reads "an adjustment above the forecast share makes the call 0 and the rest is carried to the next call". EKO''s adjustment of 600000.000000 exceeds its forecast share of 500000.000000, so its call is 0.000000 and 100000.000000 is carried. A negative call is what "refund" produces. The rest of the credit is carried and applied in October, where the reason reads "2027-10: a credit of 200000 held from 2027-09 is applied to this cash call".'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 8, 'Suppose the Ekene months are rerun as cc-ekene-2027-refund: the same two-month lag and 500000.000000 threshold, but a credit above a forecast share is paid back (the rule "refund"). What are September''s total and the year''s total of calls?', '["0.000000 in September with 200000.000000 carried to October, and 68604000.000000 over the year", "-200000.000000 in September, and 68604000.000000 over the year", "-200000.000000 in September, and 68500000.000000 over the year, the refund having settled the July over-call a month early", "1000000.000000 called in full in September"]'::jsonb, 1, 'Under "refund" the excess is paid back as a negative call of -200000.000000 in total, and the engine''s reason reads "2027-09: the adjustment exceeds the forecast share of EKO, PA, PB: the excess is refunded (a negative call)". The course prints calls over the year of 68604000.000000 for both the carried and the refunded ledger. A September of 0.000000 with 200000.000000 carried is the "carry" ledger. 68500000.000000 is the yearly total of the lag-1 ledger, a different term.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 9, 'A learner loads the Ekene 2027 ledger and sets the control "A negative call is (stated)" to not stated, which removes negativeCall from the box. What does the engine return?', '["The same ledger computed under \"refund\", which the Norwegian Accounting Agreement prints as the rule absent an agreement", "The same ledger computed under \"carry\", which the Kenya Model PSC 2015 prints as the reduction of the next advance", "A refusal only at September''s call", "A refusal: negativeCall must be one of \"refund\", \"carry\"; got nothing"]'::jsonb, 3, 'The engine holds no negative call rule, and the course prints the refusal for this very change, in the engine''s words: negativeCall must be one of "refund", "carry"; got nothing. Both public texts allow both outcomes, which is why the rule is a stated input with no default. The refusal comes before any month is computed; the engine never runs part of a ledger.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 10, 'EKO ends May 2027 with 150000.000000 carried and 224000.000000 of May spend not yet billed (lag 2, "carry", threshold 500000.000000). What is its balance with the operator?', '["-74000.000000", "150000.000000, the carried amount alone, since spend made without a call has not yet been billed and does not count", "224000.000000, the May spend the operator is owed, which the engine sets as EKO''s balance until June''s billing", "-48000.000000, the balance EKO closes the year on, which the engine carries back to each month end"]'::jsonb, 0, 'EKO''s May row prints a balance of -74000.000000. The engine''s identity reads "balance with the operator = differences not yet adjusted + carried - arrears billed and not yet paid", so May''s unbilled spend counts against the credit carried. In June the call and the arrears billing are paid and EKO''s balance returns to 0.000000.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 11, 'The course checks the closing rows of the Ekene 2027 ledger (lag 2 months, rule "carry", no call below 500000.000000). EKO closes at -48000.000000, all of it differences not yet adjusted. What does the course say the check establishes?', '["For each party, the closing balance equals its share of the year''s calls less its share of the year''s actual spend, to the cent", "The four closing balances sum to 0.000000, since whatever one party holds with the operator another owes it", "For each party, the balance less (the differences not yet adjusted + carried - arrears due) is within 0.000001 of zero", "Every closing balance is 0.000000 once the differences not yet adjusted are billed in arrears in the following month"]'::jsonb, 2, 'The course states the identity on the closing rows as derived: "for each party the balance less (the differences not yet adjusted + carried - arrears due) is within 0.000001 of zero", checked for EKO, PA, PB and NOC. It is checked within a stated bound. The closing balances of EKO, PA and PB are -48000.000000, -30000.000000 and -18000.000000, which do not cancel. An unadjusted difference is left for a later call; it is not billed in arrears.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 12, 'Drop the threshold from the Ekene ledger so that every month is called (cc-ekene-2027-every-month, lag 2, "carry"). What changes in the engine''s totals?', '["A refusal naming noCallBelow, a term with no default", "Calls of 69052000.000000 over the year, 0.000000 billed in arrears, and EKO closing at -48000.000000", "68604000.000000 in calls and 448000.000000 in arrears, as before", "69148000.000000 in calls, with EKO closing at 0.000000"]'::jsonb, 1, 'With no threshold every month is called, so nothing is billed in arrears: the engine returns calls of 69052000.000000, arrears of 0.000000 and an EKO closing balance of -48000.000000. The threshold is an optional term, applied only when stated, and the engine holds no Norwegian figure: the NOK 5 million a month is the text''s. The calls still differ from the actual, because the last two months'' differences are open at the close.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 13, 'A learner types a key "lag" into the top level of a cashCalls call, meaning the reconciliation lag. What does the engine return?', '["A ledger that reads \"lag\" as the reconciliation lag, since the engine matches an input key to the nearest accepted name", "A ledger that ignores \"lag\" and runs with no reconciliation lag at all, reporting the unknown key among its reasons", "A refusal: lag is not an accepted key; the accepted keys at the top level are parties, carries, months, reconciliationLagMonths, negativeCall, noCallBelow", "A refusal naming reconciliationLagMonths as missing, with no mention of the key \"lag\" that was typed in its place"]'::jsonb, 2, 'The engine refuses an input key it does not read, at every level, naming the key and the accepted keys: "lag is not an accepted key; the accepted keys at the top level are parties, carries, months, reconciliationLagMonths, negativeCall, noCallBelow". It never guesses a key and never silently drops a term, so a misspelt contract term cannot quietly change a call.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 14, 'NOC holds a participating interest of 20.000000 in the Ekene joint venture and is carried in full, pro rata. What does the Ekene 2027 ledger (lag 2 months, rule "carry", no call below 500000.000000) call from NOC?', '["20 percent of each month''s forecast, its participating interest, paid by the carriers on NOC''s behalf and billed to it later", "Nothing during the year, with its 20 percent share of the year''s actual spend billed in arrears in December", "Its beneficial interest of 20.000000 percent of every forecast, since cash calls follow the share of production", "0.000000 in every month, on a paying interest of 0.000000"]'::jsonb, 3, 'Every split of a joint account amount is calculatePartnerCosts on the paying interests, and NOC''s paying interest is 0.000000 under the carry; every NOC row of the ledger prints a forecast share, call and balance of 0.000000. Its beneficial interest stays 20.000000, because a carry moves cost and never moves production. The carriers pay NOC''s share through their own paying interests (EKO 50.000000, PA 31.250000, PB 18.750000); nothing is billed to NOC through the cash calls.'),
  ('joa', 'intermediate', 'module', 'm01-the-cash-call-ledger', 15, 'The golden input cc-year-boundary states parties A 50, B 30 and C 20 percent, a lag of 1 month, the rule "carry" and no threshold. December 2026 is forecast at 1000.000000 and spends 900.000000. What does the engine call in January 2027, a month forecast at 1000.000000?', '["1000.000000, as each year settles its own differences", "900.000000, with December''s over-call of 100 credited across the year boundary", "1000.000000 in January, with the 100.000000 over-call refunded in December as its own negative call", "800.000000, the 100 credited twice"]'::jsonb, 1, 'The ledger runs in consecutive months regardless of the calendar year, and the engine''s reason reads "2027-01: the over-call of 100 in 2026-12 (forecast 1000, actual 900) is credited against this cash call, 1 month later"; January''s calls total 900.000000. The stated rule is "carry", which makes no negative call, and a difference is credited once.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 1, 'The Ekene carry (synthetic) states a compound uplift of 8.000000 percent a year, carry recovery from 50.000000 percent of NOC''s share of entitlement and basis "contract". NOC''s carried cost is 16400000.000000 in 2027 and 12000000.000000 in 2028. What uplift does the engine charge in 2028?', '["2376960.000000, 8 percent of the 2028 due of 29712000.000000, the year''s uplift and carried cost both included", "1312000.000000, 8 percent of the opening balance of 16400000.000000 alone", "0.000000, since no uplift accrues until NOC''s entitlement starts", "8200000.000000, the uplift added in the first year a cost is carried"]'::jsonb, 1, 'The engine''s basis reads "8% a year on the opening balance, compounded yearly; a year''s new cost earns none in its own year", and its reason reads "2028: 8% a year on the opening balance 16400000 adds 1312000". 2376960.000000 is the 2029 uplift, charged on 2029''s opening balance of 29712000.000000. The uplift runs from the first opening balance, before any entitlement. 8200000.000000 is what the 150 percent multiple adds in 2027 on a different carry.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 2, '2033 opens with 6729407.979520 still owed on the 8.000000 percent compound Ekene carry, which may take half of NOC''s share (basis "contract"). That share is 18800000.000000. What does NOC keep?', '["9400000.000000, the half of its share that the carry recovery does not take in any year", "18800000.000000, its whole share, since the balance due is below the available amount and the carry closes", "7267760.617882, the amount the carriers recover in the year, which is what the engine credits back to NOC", "11532239.382118"]'::jsonb, 3, 'The balance due in 2033 is 7267760.617882, less than the 9400000.000000 available, so only the balance is recovered and NOC keeps 11532239.382118 of its share of 18800000.000000. The engine''s reason: "2033: the balance 7267760.62 is recovered with 7267760.62 of the 9400000 available; the carried party receives 11532239.38 of its share 18800000". The carry closes in 2033 with the balance paid out of that year''s share, so NOC keeps less than its whole share.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 3, 'The engine''s 2033 reason on the Ekene compound carry prints the balance recovered as 7267760.62. Which figure does a Professional partner report quote as the balance, and why?', '["7267760.617882, the numeric field at six decimals; the reason rounds money to the cent for reading", "7267760.62, because the reason is the engine''s own words and the field is a display figure", "The reason''s 7267760.62, padded with zeros to six decimals for the report, since a report quotes the engine''s own words", "Either one, since the two agree at the cent and so are the same figure"]'::jsonb, 0, 'The course quotes the balance as the numeric field, 7267760.617882, and quotes the reason only verbatim. The course says a reason rounds money to the cent, with trailing zeros dropped, while every numeric field keeps full precision. Two figures that agree when printed at a coarser precision are not keyed as equal, and no whole-dollar rounding is applied to a field.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 4, 'The golden input carry-ekene-pia states the Ekene carry with no uplift, carry recovery from 100.000000 percent of NOC''s share, and basis "pia-s85-4". In which year is the carry recovered, and what does NOC keep that year?', '["In 2030, when NOC''s first share of 19200000.000000 arrives and is taken whole against the balance of 28400000.000000", "In 2033, the same payout year as the compound carry, since a carry recovery share does not move the payout year", "In 2031, keeping 13200000.000000 of its share of 22400000.000000", "In 2031, keeping 11200000.000000"]'::jsonb, 2, 'Under the Act''s basis the balance stays 28400000.000000; 2030 recovers 19200000.000000 and leaves 9200000.000000, which 2031 clears: "2031: the balance 9200000 is recovered with 9200000 of the 22400000 available; the carried party receives 13200000 of its share 22400000". The golden input states carry recovery from the whole share; the engine holds no half. The compound carry runs to 2033 because its uplift grows the balance and it takes half the share.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 5, 'A learner states the Ekene carry with basis "pia-s85-4" and an uplift of { type: "compound", ratePctPerYear: 8 }. What does the engine return?', '["The compound ledger that recovers in 2033, with a note that the Act''s basis is overridden by the stated contract uplift", "A refusal naming uplift.type: it must be \"none\" under basis \"pia-s85-4\", as the refund excludes interest, premium or markups on cost (PIA s.85(4)(c))", "The Act''s ledger recovering in 2031, the stated uplift ignored", "A refusal naming basis: a carry under the Act must be stated as a contract"]'::jsonb, 1, 'The engine refuses the call, in its own words: uplift.type must be "none" under basis "pia-s85-4": the refund excludes interest, premium or markups on cost (PIA s.85(4)(c)); got "compound". A term the Act fixes is refused when a call breaks it; the engine neither overrides the basis nor drops the stated term quietly, and "pia-s85-4" is one of the two bases the engine accepts.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 6, 'In the recovery calculator a learner starts from the Ekene carry under PIA s.85(4) and sets the uplift to { type: "compound" } with no rate typed. Which refusal does the engine give first?', '["uplift.type must be \"none\" under basis \"pia-s85-4\", since the basis is checked before the terms of the uplift are read", "uplift must be an object { type } with type \"none\", \"compound\" or \"multiple\" (no default); got nothing", "None: the engine fills the missing rate with 0 and returns the Act''s ledger, recovered in 2031", "The refusal for the missing compound rate, naming uplift.ratePctPerYear"]'::jsonb, 3, 'The course prints this change as a stated probe on carry-ekene-pia, with the engine''s message "uplift.ratePctPerYear must be a finite number at or above 0; got nothing". The missing rate is refused before the Act''s bar on an uplift is reached, so a learner must state a rate to see the Act''s refusal. The uplift object is present here, so the no-uplift refusal does not fire, and the engine holds no rate of its own.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 7, 'A 150 percent multiple is stated for the Ekene carry (carry-ekene-multiple, half of NOC''s share available, basis "contract"). How is the balance due built up?', '["It adds 8200000.000000 in 2027 and 6000000.000000 in 2028, each in the year its cost is carried, fixing the due at 42600000.000000", "It adds 150 percent of the opening balance every year, compounding until the carry recovery is complete in 2034", "It adds 14200000.000000 in 2030, the first year NOC has any entitlement to recover from", "It adds nothing to the balance and takes 150 percent of each year''s carry recovery"]'::jsonb, 0, 'The engine''s reasons read "2027: the 150% multiple on the carried cost of 16400000 adds 8200000" and "2028: the 150% multiple on the carried cost of 12000000 adds 6000000". After 2028 the uplift column is 0.000000 and the due stays 42600000.000000 until it is paid down; the carry is recovered in 2034 with 42600000.000000 recovered in all. A multiple is not a yearly rate and is not deferred to the first year of entitlement.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 8, 'A contract for a carry states a multiple uplift of 90 percent, intending that the carriers forgive a tenth of the cost. What does the engine return?', '["A ledger that recovers 90 percent of the carried cost and writes the other 10 percent off in the first year of carry recovery", "A ledger identical to no uplift, since the engine floors any multiple below 100 at 100", "Refused by name, since a multiple under 100 would give back less than the cost", "A refusal naming the cap, as a partial carry recovery is written as a cap"]'::jsonb, 2, 'The engine refuses the multiple by name: "uplift.multiplePct must be a number at or above 100 (100 recovers the cost alone); got 90". It writes nothing off and floors nothing. A carry recovery limited below the cost is a cap, which is a separate optional term; the refusal here names the multiple because that is the term stated below its bound.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 9, 'Suppose the compounding Ekene carry (8 percent on the opening balance, half the share, basis "contract") is capped at 25000000.000000, as in carry-ekene-capped. What happens in 2032?', '["10400000.000000 recovered, the whole amount available, with the cap applied only to the year''s uplift", "4200000.000000 recovered, and 12929407.979520 written off as the cap is reached", "4200000.000000 recovered, and 12929407.979520 left outstanding, still owed to the carriers from later entitlement", "Nothing recovered in 2032"]'::jsonb, 1, 'By the end of 2031 the carriers have recovered 20800000.000000, so 4200000.000000 of the cap is left; the engine''s reason reads "2032: the stated cap 25000000 is reached with 4200000 recovered this year; the rest, 12929407.98, is written off". The totals show 12929407.979520 written off and 0.000000 outstanding, with the year recovered reading none. A written-off balance is gone under the contract''s terms; an outstanding one is still owed.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 10, 'The golden input carry-ekene-short-horizon runs the compound Ekene carry (8.000000 percent a year, from 50.000000 percent of the share, basis "contract", no cap) over 2027 to 2031 only. What do its totals show?', '["15860562.944000 written off at the end of 2031, as a carry not recovered by the last year is closed by the engine", "A refusal, since a carry recovery must be given enough years to recover its balance", "20800000.000000 outstanding, the amount recovered in the five years being what remains owed", "15860562.944000 outstanding and 0.000000 written off"]'::jsonb, 3, 'With no cap nothing is written off: the totals print 20800000.000000 recovered, 0.000000 written off and 15860562.944000 outstanding, and the engine''s reason reads "2031: 15860562.94 of the carry is not recovered by the last year". A carry not recovered by the last year is a result with a reason; the engine computes no year beyond the ones it was given.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 11, 'Two small golden ledgers state parties A 60, B 20 and N 20 percent, N carried, no uplift and carry recovery from 100 percent of N''s share. On carry-recovered-exactly the 2028 balance of 200.000000 meets 200.000000 available; on carry-one-short 199.800000 is available. What does the engine return?', '["The first is recovered in 2028 with N keeping 0; the second leaves 0.200000 carried to 2029 and recovered there", "Both are recovered in 2028, since 199.800000 is within the engine''s summing tolerance of the balance", "The first carries 0 to 2029 and closes there, the second writes off 0.200000", "Neither closes in 2028: a balance is closed only by a year with more available than it owes"]'::jsonb, 0, 'At the boundary the engine recovers the carry in that year: "2028: the balance 200 is recovered exactly by the 200 available; the carried party receives 0 of its share 200". One short, it carries the rest: "2028: 199.8 recovered of 200 due; 0.2 carried to 2029" and "2029: the balance 0.2 is recovered with 0.2 of the 200 available". Nothing is written off without a cap, and the summing tolerance applies to participating interests summing to 100.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 12, 'The golden input carry-cap-exactly-cost states parties A 60, B 20 and N 20 percent, a compound uplift of 10 percent, carry recovery from 100 percent of N''s share and a cap of 200, equal to N''s carried cost. What happens in 2028?', '["The cost of 200 and the uplift of 20 are both recovered, as a cap bounds the carried cost alone and leaves the uplift on top of it", "200 is recovered and 20.000000 is carried to 2029 as outstanding, since a cap delays the uplift", "The carriers get N''s cost of 200 back and lose the 20.000000 uplift to the cap", "A refusal, since a cap may not equal the carried cost"]'::jsonb, 2, 'The engine''s reasons read "2028: 10% a year on the opening balance 200 adds 20" and "2028: the stated cap 200 is reached with 200 recovered this year; the rest, 20, is written off". A cap limits the whole carry recovery, uplift included, so a cap set at the cost recovers the cost alone. Written off means gone; it is not carried to 2029.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 13, 'The golden input carry-cost-while-recovering states a compound uplift of 25 percent and carry recovery from 100 percent of the carried party''s share. 2028 opens at 100.000000, carries a new cost of 100.000000 and has 50.000000 available. What balance closes 2028?', '["200.000000, with the 25 percent uplift charged on the year''s new cost as well as on the opening balance", "225, the amount due, since nothing is recovered while the carry is still adding cost", "150.000000, as a year that carries new cost charges no uplift on its opening balance until the cost stops", "175.000000"]'::jsonb, 3, 'The engine charges the uplift on the opening balance alone (25.000000 on 100.000000), adds the year''s carried cost, and recovers from the same year''s entitlement at the year end: "2028: 50 recovered of 225 due; 175 carried to 2029". Carry recovery runs while cost is still being carried, so the due of 225 is reduced by the 50 recovered.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 14, 'On the carry with 8.000000 percent compounding, half of NOC''s share taken and basis "contract", the carriers get back 7267760.617882 in 2033. How is that sum divided?', '["To the carriers in their carry shares: EKO 3633880.308941, PA 2271175.193088, PB 1362705.115853", "All of it to EKO as operator, which settles with PA and PB outside the carry recovery ledger", "To EKO, PA, PB and NOC by their beneficial interests of 40, 25, 15 and 20 percent", "To the joint account, where it reduces the next cash call of every paying party"]'::jsonb, 0, 'The course prints the 2033 party flows: EKO recovery 3633880.308941, PA 2271175.193088, PB 1362705.115853 and NOC -7267760.617882, and states that the recovered amount goes to the carriers in their carry shares. NOC is the party paying the carry recovery, so it receives none of it, and the carry recovery is settled through the party flows of the carry recovery ledger.'),
  ('joa', 'intermediate', 'module', 'm02-carries-with-uplift-and-caps', 15, 'At a discount rate of 0.100000 to a base year of 2027, what NPV does the engine return for NOC on the Ekene compound carry (8.000000 percent a year, from 50.000000 percent of its share, basis "contract") and on carry-ekene-pia (no uplift, from 100.000000 percent, basis "pia-s85-4")?', '["54584252.437515 on the compound carry and 49870804.456959 under the Act, as the uplift is paid to NOC", "49870804.456959 on the compound carry and 54584252.437515 on the carry under the Act", "49870804.456959 on both, since NPV is computed on the carried cost alone", "47640894.676658 on the compound carry, the lowest of the three carries"]'::jsonb, 1, 'The canonical npv returns NOC 49870804.456959 on the compound carry and 54584252.437515 on the Act''s carry: the uplift moves value from the carried party to its carriers. 47640894.676658 is NOC''s NPV under the 150 percent multiple, a different term. Each NPV is quoted with its rate and base year because it depends on both.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 1, 'On the Ekene joint venture (synthetic) NOC backs in from a participating interest of 20.000000 to 40.000000 percent under basis "pia-s85-4". What participating interests does the engine return for EKO, PA and PB after the back-in?', '["EKO 20.000000, PA 25.000000 and PB 15.000000, the operator alone ceding the 20 points", "EKO 40.000000, PA 25.000000 and PB 15.000000, as a back-in moves cost shares and leaves the participating interests as they were", "EKO 30.000000, PA 18.750000 and PB 11.250000, each keeping 60 / 80 of its participating interest", "EKO 20.000000, PA 12.500000 and PB 7.500000, each giving up half its participating interest"]'::jsonb, 2, 'The engine''s rule reads "new interest of another party = old x (100 - target) / (100 - current)", and its reason "NOC backs in from 20% to 40%: the others keep 60 / 80 of their interests"; the table prints EKO 30.000000, PA 18.750000 and PB 11.250000. EKO 20.000000, PA 12.500000 and PB 7.500000 are the participating interests after a back-in to 60, where the others keep 40 / 80. A back-in changes participating interests; that is what distinguishes it from a carry.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 2, 'The Ekene back-in golden input backin-ekene-pia states six cost lines, NOC''s move from 20 to 40 percent, basis "pia-s85-4" and a refund from future entitlement. What refund does the engine return?', '["98000000.000000: 20 percent of refundable costs of 490000000.000000, with 156000000.000000 excluded", "490000000.000000: the refundable costs in full, since the Act says the Government shall refund fully", "196000000.000000: 40 percent of the refundable costs, NOC''s new participating interest", "125200000.000000: 20 percent of the costs left once the bonus, the interest line and the markup are taken out"]'::jsonb, 0, 'The engine''s reason reads "NOC backs in from 20% to 40%: the others keep 60 / 80 of their interests; refund 20% x refundable costs 490000000 = 98000000 (156000000 excluded)". The refund is the change in participating interest (target less current) times the refundable costs. 196000000.000000 is the refund of the back-in to 60, a change of 40 points. 125200000.000000 is the contract-basis refund, which leaves the exploration wells in; the Act refunds development and production only.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 3, 'Which of the Ekene back-in cost lines does the engine count as refundable under basis "pia-s85-4"?', '["The exploration wells Ekene-1 and Ekene-2, 136000000.000000, as proven costs incurred before participation", "The signature bonus of 10000000.000000, since a bonus paid for the licence is an unrecovered cost of the venture", "The operator markup on shared services, 2000000.000000, since it is part of what the joint account paid", "Front end engineering design, 40000000.000000 of development cost"]'::jsonb, 3, 'The engine''s basis reads "development and production costs only; bonuses, penalties, interest, premium and markups excluded (PIA s.85(4)(c)); exploration is not development or production", and the cost line table marks front end engineering design (development) refundable. Each of the other three prints a reason that it is not refundable, citing PIA s.85(4)(c).'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 4, 'Could NOC take 61 percent under the Act? A learner types targetPct 61 with basis "pia-s85-4" to find out. What happens?', '["A back-in computed at 60 percent, the most the Act allows, with the extra point reported and set aside", "A refusal: targetPct must be at most 60 under basis \"pia-s85-4\" (the right to participate up to 60%, PIA s.85(4)(a)); got 61", "A back-in to 61 percent, since the Act lets the ceiling be set as a bid parameter", "A refusal naming refundableKinds, as the Act reads a target over 60 as a stated list of costs"]'::jsonb, 1, 'The engine refuses the target in its own words, citing s.85(4)(a): targetPct must be at most 60 under basis "pia-s85-4" (the right to participate up to 60%, PIA s.85(4)(a)); got 61. It does not cap the target silently. A target of exactly 60 is accepted (backin-pia-at-60), which is the boundary. The Act''s words about a bid parameter do not make the engine accept 61 under its basis.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 5, 'Under basis "pia-s85-4", what does the engine return for a back-in whose target equals the back-in party''s current participating interest of 20?', '["A result with no change of participating interests and a refund of 0.000000, reported with its reason", "A refusal naming refundForm, since a back-in with no change of participating interest has nothing to refund", "A refusal: targetPct must be above the back-in party''s current interest 20; got 20", "The Ekene back-in to 40 percent, the engine reading a target at the current participating interest as a doubling"]'::jsonb, 2, 'The course prints the refusal "targetPct must be above the back-in party''s current interest 20; got 20". A back-in raises the back-in party''s participating interest, so a target at its current figure is refused before any refund is computed, and the engine reads no target it was not given.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 6, 'NOC''s refund is to be paid in one sum on entry, the contract says (refundForm "upfront"), and the call is made under the Act''s basis. What comes back?', '["Refused, since the Act allows no upfront payment and takes the refund from future entitlement", "The refund paid in full in the year of the back-in, since s.85(4)(f) lets the Government''s refund be made in cash", "A refund from future entitlement, the engine substituting the Act''s form for the stated one", "The refund of 125200000.000000 that the contract-basis case returns"]'::jsonb, 0, 'The engine''s message reads: refundForm must be "from-future-entitlement" under basis "pia-s85-4": no upfront payment by the Government (s.85(4)(d)); the refund is in cash or in kind from future production or entitlements (s.85(4)(f)); got "upfront". A term the Act fixes is refused when a call breaks it; the engine substitutes nothing. Cash under s.85(4)(f) is cash from future entitlement.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 7, 'A learner copies the Ekene back-in under basis "pia-s85-4" and adds refundableKinds: ["exploration"] so that the exploration wells are refunded. What does the engine return?', '["A refund of 125200000.000000, as a stated list replaces the Act''s kinds", "The Act''s refund of 98000000.000000, with the stated list set aside in a reason", "A refusal naming costs[0].kind, since exploration is not one of the kinds the engine accepts on a cost line", "Refused, because under the Act the kinds are fixed at development and production and may not be listed"]'::jsonb, 3, 'The engine refuses: refundableKinds must be left out under basis "pia-s85-4" (development and production, s.85(4)(c)); got ["exploration"]. Under the Act the kinds are fixed, and a stated list is a contract-basis term. Exploration is an accepted kind on a cost line; the engine simply does not refund it under the Act.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 8, 'The golden input backin-ekene-contract-upfront states the same six Ekene cost lines under basis "contract" with refundable kinds that include exploration, and refundForm "upfront". What refund does the engine return?', '["98000000.000000, as the Act''s exclusions apply to every back-in whatever basis is stated", "125200000.000000 on refundable costs of 626000000.000000, with 20000000.000000 excluded", "156000000.000000, the excluded amount, which a contract basis refunds in place of the Act''s kinds", "196000000.000000, the refund of a back-in to 60 percent"]'::jsonb, 1, 'Under basis "contract" the stated kinds decide: the engine refunds 20 percent of 626000000.000000, which is 125200000.000000, and excludes the bonus, the interest line and the markup (20000000.000000) with the reason "not a stated refundable kind". The Act''s list applies only under basis "pia-s85-4".'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 9, 'On the Ekene back-in under the Act, NOC''s refund of 98000000.000000 is recovered from 50.000000 percent of its new share of future entitlement. In which year is it recovered, and what does NOC receive that year?', '["In 2033, receiving 18800000.000000, as the balance of 35600000.000000 is cleared from the whole share that year", "In 2034, receiving 17200000.000000, the half of its share the refund recovery does not take", "In 2034, receiving 17600000.000000 of its share of 34400000.000000", "In 2031, the year the Ekene carry under the Act is recovered, since both run on the same entitlement"]'::jsonb, 2, 'The engine''s reason reads "2034: the balance 16800000 is recovered with 16800000 of the 17200000 available; the back-in party receives 17600000 of its share 34400000". The refund recovery takes only the balance in its last year, so NOC keeps more than half its share. The refund recovery share is stated at 50 percent, so no year takes the whole share. The carry under the Act recovers a different, smaller balance from a different share.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 10, 'The golden input backin-pia-at-60 takes NOC from 20 to 60 percent under basis "pia-s85-4", recovering the refund from 50.000000 percent of its new share over 2030 to 2036. What do the totals show?', '["196000000.000000 refunded, 192000000.000000 recovered and 4000000.000000 outstanding, recovered in year none", "A refusal, since 60 is the Act''s ceiling and a target at the ceiling is outside it", "196000000.000000 recovered in 2036, the balance being cleared from the whole share in the last year", "196000000.000000 refunded with 4000000.000000 written off in 2036"]'::jsonb, 0, 'A target equal to 60 is accepted (the boundary), and the refund of 196000000.000000 is 40 percent of 490000000.000000. By 2036 192000000.000000 has been recovered: "2036: 4000000 of the refund is not recovered by the last year". Outstanding means still owed; nothing is written off, because a back-in states no cap.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 11, 'The small golden input backin-recovered-on-last-year takes N from 20 to 40 percent (parties A 60, B 20, N 20) with refundable costs of 1000.000000 and refund recovery from 50.000000 percent of N''s new share. In 2031 the balance of 100.000000 meets 100.000000 available. What does the engine return?', '["100.000000 carried to 2032, since a balance is cleared only when more is available than is due", "The refund is recovered in 2030, when the first 100.000000 is taken", "The refund is recovered in 2031 and N receives 0, the whole share going to A and B", "The refund is recovered in 2031, exactly, and N receives 100 of its share 200"]'::jsonb, 3, 'The engine''s reason reads "2031: the balance 100 is recovered exactly by the 100 available; the back-in party receives 100 of its share 200". Available equal to the balance clears it in that year. Only half of N''s share is available, so N keeps the other half; 2030 recovers 100 of the 200 due.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 12, 'On the Ekene back-in to 40 percent under the Act, how does the engine divide NOC''s refund of 98000000.000000 among the other parties?', '["By their participating interests after the back-in, EKO 30.000000, PA 18.750000 and PB 11.250000, so EKO receives the most", "In proportion to the participating interest each gives up: EKO 49000000.000000, PA 30625000.000000, PB 18375000.000000", "Equally among the three, since the Act refunds the Government''s share with no stated split", "Wholly to EKO as operator, which paid the costs on the joint account and holds the refund for the others"]'::jsonb, 1, 'The engine''s rule reads "refund = (target - current) / 100 x refundable costs, received in proportion to the interest given up". EKO gives up 10.000000 points, PA 6.250000 and PB 3.750000, and the table prints refunds of 49000000.000000, 30625000.000000 and 18375000.000000. The split follows the points given up; the refund is not held by the operator.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 13, 'Section 85(4) of the Act opens "A contract as provided for under section 85 (2) (d)". Which contract does that name, and when does the engine apply the s.85(4) figures?', '["The production sharing contract of s.85(2)(a); the engine applies the 60 percent ceiling to every PSC it computes", "Every contract under the Act; the engine applies the figures to any call that names NOC as a party", "The concession agreement that may include a joint venture with NNPC Limited; the figures apply only under a stated basis \"pia-s85-4\"", "The renegotiated PSC of s.311(2)(a)(iii); the figures apply whenever a cost oil limit is stated"]'::jsonb, 2, 'The course reads s.85(4) as opening on the contract of s.85(2)(d), which is the concession agreement that may include a joint venture with NNPC Limited; a production sharing contract is s.85(2)(a). The engine applies the s.85(4) figures only under basis "pia-s85-4", which the caller states. A party''s name decides nothing, and s.311(2)(a)(iii) is the renegotiated PSC''s cost oil limit, reported in a basis only.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 14, 'PIA s.85(4)(e) says the unrecovered costs to be refunded are settled by an agreed expert determination procedure. What does the engine do about that procedure?', '["It applies a haircut to each stated cost line in place of the procedure", "It refunds only the cost lines marked verified, and treats every other line as excluded under s.85(4)(c)", "It reports the Ekene back-in refund as provisional until a determination is stated as an input", "It computes none of it: the unrecovered cost figures are stated inputs"]'::jsonb, 3, 'The engine''s basis says, in its own words: the expert determination of the unrecovered costs (s.85(4)(e)); the unrecovered cost figures are stated inputs. It applies no haircut (that is s.311(2)(a)(iii), for disputed amounts in a renegotiated PSC, and the engine computes none), reads no verification flag, and returns the refund of 98000000.000000 as a figure on the stated costs.'),
  ('joa', 'intermediate', 'module', 'm03-back-in-under-the-act', 15, 'A cost line in a back-in call states kind "appraisal". What does the engine return?', '["A refusal naming costs[0].kind, which must be one of the eight kinds from \"exploration\" to \"markup\"", "A back-in that counts the appraisal line as development, the nearest refundable kind under the Act", "A back-in that excludes the line with the reason that appraisal is not a stated refundable kind, as under a contract basis", "A back-in that refunds the line in full, since the Act excludes only the kinds it names"]'::jsonb, 0, 'The engine''s message reads: costs[0].kind must be one of "exploration", "development", "production", "bonus", "penalty", "interest", "premium", "markup"; got "appraisal". It maps no unknown kind onto a known one, so a cost line''s kind must be stated as one of the eight before any refund is computed.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 1, 'PB leaves 2000000.000000 of its Ekene cash call unpaid from 2027-03-01 until 2027-04-15, and NOC is carried. Which parties advance the shortfall, as the engine states its cover?', '["EKO, PA and NOC in proportion to their participating interests of 40, 25 and 20 percent, NOC included as a party to the venture", "EKO 1230769.230769 and PA 769230.769231, in proportion to their paying interests among the non-defaulting parties", "EKO alone, as operator, which advances every unpaid amount and recovers it from PB with the default interest", "EKO 1000000.000000 and PA 1000000.000000, the two paying parties sharing the unpaid amount equally"]'::jsonb, 1, 'The engine''s stated cover reads "the non-defaulting parties advance the unpaid amounts in proportion to their paying interests among themselves (the parties that pay cost; a carried party pays none)", and it returns EKO 1230769.230769 and PA 769230.769231, 61.538462 and 38.461538 percent of the cover. This is the engine''s stated reading of the cover: NOC, carried, pays no cost and covers none. The operator does not cover alone while another paying party is not in default.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 2, 'PB''s Ekene default (synthetic): PB pays 250000.000000 of its 2250000.000000 share of the 12000000.000000 call due 2027-03-01, cures on 2027-04-15, and the contract states default interest at 8.250000 percent a year, simple, on a 360-day basis with a grace of 0 hours. What default interest does the engine return?', '["20342.465753, the same 45 days on a 365-day year, the calendar the engine counts days on", "20210.781250, the default interest compounded monthly as the Kenya model prints it", "55916.666667, counted to 2027-07-01 as though the default were still open at the close", "20625.000000, on 45 days"]'::jsonb, 3, 'The engine''s reason reads "PB: share of the call 2250000, paid 250000, unpaid 2000000; interest 2000000 x 8.25% x 45 days / 360 = 20625 (from 2027-03-01 to the cure on 2027-04-15, the last date excluded)". The day basis is a stated term: 20342.465753 is the same default on a 365-day basis, which the contract here does not state. 20210.781250 needs the method "monthly-compound". 55916.666667 belongs to the uncured case at 2027-07-01.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 3, 'How does the engine count the days of default interest between the due date 2027-03-01 and a cure on 2027-04-15?', '["From and including the due date to, but excluding, the cure date: 45 days", "From the day after the due date to and including the cure date, the way a loan accrues from its drawdown", "Whole months only, the part-month ignored", "From the end of the stated grace to the cure date, since default interest cannot start inside a grace"]'::jsonb, 0, 'The Norwegian Accounting Agreement Art. 1.2.2 prints "Interest is due for the period starting on and including the due date of payment and ending on, but excluding, the value date for payment.", and the engine''s basis says the same: "from and including the due date to, but excluding, the cure date (or asOf)"; the table prints 45 days for this default. Whole months enter only the monthly-compound method, and on a default cured after the grace the engine runs default interest from the due date.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 4, 'PB''s Ekene shortfall of 2000000.000000, open from 2027-03-01 to 2027-04-15, is priced at 8.250000 percent, simple, with a 0-hour grace, but on a 365-day basis. What comes back?', '["20625.000000, since the day basis only changes the count of days and 45 days is 45 days on either", "A refusal: the engine accepts a 360-day basis only, as the Norwegian agreement prints", "20342.465753 for the same 45 days", "20625.000000 times 365 / 360, the 360-day figure scaled up to a calendar year"]'::jsonb, 2, 'The course prints the stated probe: "The same Ekene default on a 365-day basis ... gives 20342.465753 for the same 45 days, against 20625.000000 on the 360-day basis the fixture states". Dividing by 365 gives the smaller figure. The engine accepts 365 or 360 and refuses anything else ("interest.dayBasis must be 365 or 360; got 366"); scaling the 360-day figure up would move it the wrong way.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 5, 'The golden input default-ekene-monthly-compound-kenya states PB''s Ekene default (unpaid 2000000.000000 from 2027-03-01, cured 2027-04-15) at 8.250000 percent, monthly-compound, 360-day basis, grace 72 hours. What does the engine return?', '["20625.000000, as with the simple method", "0.000000, the grace cancelling it", "20342.465753, on a calendar year", "20210.781250: one whole month compounded and 14 days simple"]'::jsonb, 3, 'The engine''s reason prints the formula: "interest 2000000 x ((1 + 8.25% / 12)^1 x (1 + 8.25% x 14 days / 360) - 1), 1 whole month and 14 days = 20210.78", with the field 20210.781250. On the same default the simple method gives 20625.000000. The grace of 72 hours is exceeded, so default interest runs from the due date, as the engine states the Kenya clause.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 6, 'Seventy-two hours of grace are written into a contract (default-grace-last-hour: 8.25 percent simple, 360 days). The late partner settles on 2027-03-04, exactly three days after the due date. What does the engine charge?', '["1375.000000 on 3 days, since a grace only postpones the start of default interest and never cancels it", "No default interest: 3 days (72 hours) are within the stated grace", "1833.333333 on 4 days, the cure day counted", "0.000000 for three days, then default interest from the cure date on the rest of the month"]'::jsonb, 1, 'The engine''s reason reads "PB: share of the call 2250000, paid 250000, unpaid 2000000; no interest: 3 days (72 hours, from 2027-03-01 to the cure on 2027-03-04, the last date excluded) are within the stated grace of 72 hours". Cured exactly at the grace is inside it, which is the boundary, and the engine''s stated grace charges nothing within it. 1375.000000 is the 3-day figure of the 71.5-hour grace, which is exceeded.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 7, 'On default-grace-exceeded (8.25 percent simple, 360 days, a grace of 72 hours) the late partner pays on 2027-03-05, four days after the due date. Reading the grace as the engine states it, what is charged?', '["Default interest on the one day past the grace alone, as it starts only when the grace ends", "0.000000, the grace read as three whole days", "1833.333333 on 4 days, with default interest running from the due date", "1375.000000 on 3 days"]'::jsonb, 2, 'The engine''s stated grace reads "a default cured within it carries no interest; one cured later carries interest from the due date, as the Kenya Model PSC 2015 Participation Agreement Art. 6.7 prints (72 hours)". Cured after 4 days (96 hours), default interest runs over all 4 days: "interest 2000000 x 8.25% x 4 days / 360 = 1833.33". This is the engine''s stated reading of the Kenya clause, and the course grades no figure that depends on it.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 8, 'Suppose a contract''s grace were 71.5 hours at 8.25 percent simple over 360 days (default-grace-fractional-hours) and payment lands on 2027-03-04, seventy-two hours after the due date. What figure comes back?', '["1375.000000 on 3 days, the 71.5-hour grace being exceeded", "0.000000, as 71.5 hours rounds to three days and the cure falls inside it", "A refusal: whole hours only", "1833.333333, counting the half-hour past the grace as a whole further day"]'::jsonb, 0, 'Seventy-two hours have passed, which is more than 71.5, so the grace is exceeded, and as the engine states its grace, default interest runs from the due date over all 3 days: 1375.000000. Hours are compared as stated; the engine rounds no grace to whole days, and a fractional grace is a valid input.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 9, 'A learner types interestMethod "compound" into the recovery calculator''s box for the Ekene default, a word the method control does not offer. What does the engine return?', '["20210.781250, reading \"compound\" as monthly compounding, the only compounding the engine computes", "Daily compounding on the stated day basis", "20625.000000, with the unknown method ignored and simple default interest applied in its place", "Refused by name: the method takes only the words \"simple\" and \"monthly-compound\""]'::jsonb, 3, 'The engine refuses the word it does not accept, naming the field: interest.interestMethod must be one of "simple", "monthly-compound"; got "compound". The method is a stated term with no default: "simple" and "monthly-compound" are the two it computes, and it maps no other word onto either.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 10, 'A contract gives no grace at all, and the learner leaves graceHours out of the default interest terms. What does the engine return?', '["The Kenya model''s 72 hours, the only grace a public text this course reads prints", "A refusal: graceHours must be stated, 0 when the contract gives no grace, since the engine holds no default", "A grace of 0 hours, filled in by the engine and reported in its basis", "The default interest with no grace test at all, since a missing grace means none applies"]'::jsonb, 1, 'The engine''s message reads "interest.graceHours must be a finite number of hours at or above 0, stated (0 when the contract gives no grace; the engine holds no default); got nothing". A contract with no grace is stated as 0. The Kenya figure is the model''s, and the engine takes none of it as a fallback.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 11, 'Suppose PB is recorded as having paid 2250000.000000, its full share of the Ekene call, while still listed as a defaulter. What happens?', '["A refusal naming defaulters[0].paid: a party that paid its share is not in default", "A default of 0.000000 unpaid, with 0.000000 of default interest and no consequence triggered", "A default covered in full by EKO and PA, since PB is still named among the defaulters", "PB''s default interest on the whole 2250000.000000, the paid amount read as the amount outstanding"]'::jsonb, 0, 'The engine''s message reads "defaulters[0].paid must be below the party''s share of the call 2250000 (a party that paid its share is not in default); got 2250000". Paid equal to the share is the boundary, and it is refused; the engine does not return a zero default.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 12, 'The golden input default-two-defaulters has PB pay 0.000000 of its 2250000.000000 share and PA pay 750000.000000 of its 3750000.000000 share of a call due 2027-03-01. Who covers the 5250000 unpaid, as the engine states its cover?', '["EKO and NOC, in proportion to their participating interests of 40 and 20 percent", "EKO for its own share and PB and PA for each other, pro rata to their paying interests", "EKO alone, 5250000.000000, as the only non-defaulting party with a paying interest", "Nobody: with two defaulters the engine refuses the call as leaving too few paying parties"]'::jsonb, 2, 'The engine returns EKO covering 5250000.000000 (100.000000 percent): "the unpaid 5250000 is advanced by EKO 5250000, in proportion to their paying interests among the non-defaulting parties". NOC is carried and pays none. A call is refused only when no non-defaulting party with a paying interest above 0 is left.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 13, 'A learner names EKO, PA and PB as defaulters on the Ekene call. What does the engine return?', '["A cover by NOC of the whole call, NOC being the one party still not in default", "Three defaults with no cover, each accruing default interest and reported with its consequences", "A cover split among the three defaulters pro rata, as each advances the others'' unpaid amounts", "A refusal: defaulters must be leaving at least one non-defaulting party with a paying interest above 0"]'::jsonb, 3, 'The engine''s message reads: defaulters must be leaving at least one non-defaulting party with a paying interest above 0; got ["EKO","PA","PB"]. NOC''s paying interest is 0.000000 under the carry, so it cannot cover, and a defaulter never covers another.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 14, 'Suppose PB, in default on the Ekene call due 2027-03-01, pays up on 2027-04-15. Its contract states suspension after 5 working-days from 2027-03-01 and forfeiture after 3 months from 2027-03-10. Which consequences does the engine report as triggered?', '["Suspension triggered after 2027-03-08; forfeiture, due after 2027-06-10, left untriggered", "Neither triggered, since a default cured before the forfeiture date clears every consequence", "Both triggered, since both run from dates earlier than the cure on 2027-04-15", "Suspension triggered five calendar days on, with forfeiture triggered too"]'::jsonb, 0, 'The engine reads "each applies when the default is open after the whole trigger date; working days are Monday to Friday less the stated holidays; months keep the day of the month". Its reasons: suspension "starts after 5 working days from 2027-03-01, that is after 2027-03-08: triggered", and forfeiture "arises after 3 months from 2027-03-10, that is after 2027-06-10: not triggered, the default being cured on 2027-04-15". The engine reports each consequence only as the contract states it.'),
  ('joa', 'intermediate', 'module', 'm04-default-cover-and-interest', 15, 'On default-ekene-uncured PB''s default (8.250000 percent, simple, 360-day basis, grace 0 hours) is still open at 2027-07-01, after the forfeiture trigger. What does the engine report if PB''s assignment is demanded?', '["EKO 61.538462 and PA 38.461538, the assigned participating interest following the cover by paying interest", "Participating interests of EKO 47.058824, PA 29.411765 and NOC 23.529412, the compensation not computed", "The compensation for PB''s share at its book value, computed by the engine, with PB''s participating interest shared pro rata among the others", "A forfeiture to EKO alone as operator, PB''s 15 points moving whole to the party that advanced the larger part of its cover"]'::jsonb, 1, 'The engine''s reason reads "if the assignment of PB is demanded, the interest is apportioned pro rata: EKO 47.05882352941177%, PA 29.41176470588235%, NOC 23.529411764705884%; the compensation (at most the book value less unpaid contributions) is not computed". The assigned participating interest is pro rata to the others'' participating interests, NOC included; the compensation is reported only.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 1, 'The Ekene PSC variant (synthetic) states royalty 12.500000 percent, a cost oil limit of 60.000000 percent of gross, a contractor profit share of 60.000000 percent, tax 30.000000 percent and an opening pool of 142000000.000000. In 2030 gross revenue is 219000000.000000 and the pool entering the year with its capex and opex is 532000000. What cost does the engine recover, and what pool is carried to 2031?', '["114975000.000000 recovered on 60 percent of the revenue after royalty, and 417025000.000000 carried", "191625000.000000, all revenue after royalty", "131400000.000000 recovered, the limit binding, and 400600000.000000 carried to 2031", "131400000.000000 recovered, and 422000000.000000 carried, the year''s own capex and opex held back until the older pool clears"]'::jsonb, 2, 'The limit is 60 percent of gross, 131400000.000000, and the engine''s reason reads "2030: recoverable 532000000 is above the cost oil limit 131400000; 400600000 carried to 2031". 114975000.000000 and 417025000.000000 are the same year with the limit stated on revenue after royalty, a different stated base. The limit caps the cost recovered, so the whole revenue after royalty is never taken as cost oil here.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 2, 'The same percentage, 60.000000, is stated on two bases for the Ekene PSC variant (royalty 12.500000 percent). What cost oil limit does the engine return in 2030 on each?', '["131400000.000000 on gross and 114975000.000000 on revenue after royalty", "131400000.000000 on both, since a limit is always read on gross revenue as the World Bank note states it", "114975000.000000 on both, since applyPSC takes the limit on revenue after royalty whatever the contract says", "114975000.000000 on gross and 131400000.000000 on revenue after royalty"]'::jsonb, 0, 'The course prints: "In 2030 the limit is 131400000.000000 on gross and 114975000.000000 on after-royalty with the same percentage (engine). The base is a required input: a contract states which it means." The engine passes a gross limit to applyPSC as a fraction of revenue after royalty, so the base the contract states is kept.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 3, 'A contract writes its cost oil limit as 60 percent of gross, with royalty at 12.5 percent. The canonical applyPSC takes a limit on revenue after royalty. How does the engine hand it the stated limit?', '["As 60 percent of revenue after royalty, the stated figure applied unchanged to applyPSC''s own base", "As 60 percent of gross, after rewriting applyPSC''s limit calculation for a gross base", "As the stated 60 less the royalty rate of 12.5, taken as a percentage of revenue after royalty", "As the fraction 60 / (100 - 12.5) of revenue after royalty"]'::jsonb, 3, 'The engine''s basis reads "the limit is stated on gross revenue and passed to applyPSC as the fraction 60 / (100 - 12.5) of revenue after royalty". Passing 60 unchanged would put the limit on the wrong base, and the engine re-computes nothing of applyPSC: "nothing here re-computes the cost pool".'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 4, 'A learner states a cost oil limit of 90 percent of gross with royalty 12.500000 percent. What does the engine return?', '["A PSC run in which the limit is cut back to 87.5 percent of gross, with the cut reported among the reasons", "A refusal: costOilLimitPct must be at or below the revenue left after royalty, 87.5% of gross, when costOilLimitBase is \"gross\"", "A PSC run with the limit at 90 percent of gross, the royalty taken from the contractor''s cost oil", "A refusal citing the Act''s ceiling of 60 percent on the cost oil limit of every production sharing contract"]'::jsonb, 1, 'The engine refuses the stated limit in its own words, with the got value 90. A limit on gross above what royalty leaves cannot be passed to applyPSC as a fraction of revenue after royalty. The engine does not cut the limit back. The Act''s 60 percent of s.311(2)(a)(iii) applies to a renegotiated PSC and is reported in a basis only; the limit is the contract''s stated figure.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 5, 'Tax is stated at 30.000000 percent, and in 2030 the Ekene variant leaves the contractor profit oil of 36135000.000000. As the engine states the PSC income tax, what tax does it return for the year?', '["30 percent of the whole profit oil of 60225000.000000, taken before the split", "0.000000, since cost recovery carries the contractor''s tax inside the government''s profit oil", "10840500.000000, 30 percent of the contractor''s profit oil", "30 percent of the contractor entitlement of 156694500.000000, cost oil included"]'::jsonb, 2, 'The engine''s stated reading reads "income tax is charged on the contractor''s profit oil share, as FARI TNM/16/01 and World Bank Note 8 assume (applyPSC in engines/economics/cashflow.ts)", and its 2030 row prints tax 10840500.000000 on contractor profit oil of 36135000.000000. It is the engine''s stated reading, and the course grades no tax figure that depends on it.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 6, 'On psc-ekene (royalty 12.5, limit 60 of gross, contractor share 60, tax 30, 142000000.000000 carried in), which year clears the last of the pool, and how does that year''s cost recovered compare with its limit?', '["2036: 67313600.000000 recovered against a limit of 69831600.000000, and 0.000000 carried", "2035: 77590200.000000 recovered at the limit, which clears the pool of 41313600.000000 carried in", "2036: 69831600.000000 recovered at the limit, with the excess over the pool paid to the government", "2038: the pool is never cleared, and the rest is carried beyond the last year"]'::jsonb, 0, 'In 2036 the recoverable amount is below the limit, so the engine recovers the pool with the year''s opex and carries 0.000000: its row prints cost recovered 67313600.000000 against a limit of 69831600.000000. In 2035 the limit binds and 41313600.000000 is carried to 2036. The totals show 0.000000 unrecovered at the end on the gross base.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 7, 'By 2037 the Ekene variant''s pool is empty. Revenue after royalty is 91653625.000000, opex 27000000.000000 and the limit 62848200.000000. What profit oil comes back?', '["The revenue after royalty less the whole limit of 62848200.000000, as a limit is always taken in full", "91653625.000000, the whole revenue after royalty", "38792175.000000, the whole profit oil after the split", "64653625.000000, the revenue after royalty less the 27000000.000000 recovered"]'::jsonb, 3, 'The engine''s rule reads "cost recovered = min(pool + capex + opex, limit); profit oil = revenue after royalty - cost recovered". With no pool, cost recovered is the opex of 27000000.000000, below the limit, and the 2037 row prints profit oil of 64653625.000000. 38792175.000000 is the contractor''s profit oil, its 60 percent share.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 8, 'The golden input psc-ekene-after-royalty states the Ekene PSC variant (royalty 12.500000 percent, share 60.000000, tax 30.000000, opening pool 142000000.000000) with the limit at 60.000000 percent of revenue after royalty. What pool does the engine carry out of 2038?', '["0.000000, as on the gross base", "33686775.000000, the pool not being cleared within the years stated", "83179575, the recoverable amount of 2038", "33686775.000000 written off at the end of 2038, since applyPSC writes off what the years leave"]'::jsonb, 1, 'The engine''s reason reads "2038: recoverable 83179575 is above the cost oil limit 49492800; 33686775 carried to 2039". The smaller limit on revenue after royalty leaves the pool open at the end of the years stated. The engine carries it; it writes nothing off.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 9, 'Summing 2029 to 2038 of the Ekene PSC variant, whose limit is 60.000000 percent of gross after a 12.500000 percent royalty, with 142000000.000000 carried in, what cost recovered and unrecovered balance does the engine report?', '["Cost recovered 422000000.000000, the pool at the end of 2029, as later years'' costs are not recoverable", "Cost recovered 738000000.000000, with 142000000.000000 left unrecovered from the pool the contract opened with", "Cost recovered 738000000.000000, with 0.000000 unrecovered at the end", "Cost recovered 921059257.500000"]'::jsonb, 2, 'The totals print cost recovered 738000000.000000, contractor entitlement 921059257.500000 and 0.000000 unrecovered at the end. The opening pool is recovered with the later capex and opex, and the entitlement is a different line from cost recovered.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 10, 'A learner leaves openingCostPool out of the Ekene PSC call, meaning that no cost is carried in. What does the engine return?', '["A run with an opening pool of 0.000000", "A run with the fixture''s pool of 142000000.000000", "A refusal naming costOilLimitBase, which must be stated before the pool can be read", "A refusal naming openingCostPool, a required term even when nothing is carried in"]'::jsonb, 3, 'The opening pool is a required term with no default, and the engine refuses it by name: openingCostPool must be a finite number at or above 0; got nothing. A contract with no pool carried in states 0. The engine holds no Ekene figure; the fixture''s 142000000.000000 is a stated input.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 11, 'A learner states costOilLimitBase as "net". What does the engine return?', '["A refusal: costOilLimitBase must be one of \"after-royalty\", \"gross\"; got \"net\"", "A run on revenue after royalty, per IMF WP/24/89", "A run on gross, the World Bank note''s base", "A run on revenue net of royalty and cost"]'::jsonb, 0, 'The engine accepts only the two bases it names and refuses any other word. A text saying production shared is "usually net of royalties" does not make the engine read "net" as a base: the base is stated by the contract, and a word the engine does not accept is refused with its value.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 12, 'Suppose royaltyPct is typed as 100 in the recovery calculator''s PSC view. What comes back?', '["A run with all of gross paid as royalty", "A refusal naming royaltyPct, whose bound stops short of 100 itself", "A royalty capped at 87.5", "A refusal naming the cost oil limit, which cannot be passed on revenue after royalty of zero"]'::jsonb, 1, 'The engine''s message reads "royaltyPct must be a number from 0 up to, but excluding, 100; got 100". A royalty of 100 would leave no revenue after royalty for applyPSC to take the limit on, so the royalty itself is refused at its bound.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 13, 'Partners EKO 40, PA 25, PB 15 and NOC 20 percent hold the Ekene PSC variant with no carry stated. How is its 2029 capex of 280000000.000000 split between them?', '["By paying interest under the Ekene carry, EKO 50.000000, PA 31.250000 and PB 18.750000 of the capex, NOC 0.000000", "Wholly to EKO as operator, which recovers it through cost oil before any partner split", "By participating interest through calculatePartnerCosts: EKO -112000000.000000, PA -70000000.000000, PB -42000000.000000, NOC -56000000.000000", "By beneficial interest to the three carriers only, NOC''s share paid by them"]'::jsonb, 2, 'The engine''s basis reads "the contractor entitlement and the costs are split by participating interest with calculatePartnerCosts from engines/economics/afe.js", and its 2029 row prints EKO -112000000.000000, PA -70000000.000000, PB -42000000.000000 and NOC -56000000.000000. The PSC variant states no carry, so every partner pays by its participating interest.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 14, 'A learner gives the first year of a PSC call its own contractorProfitSharePct of 120. What does the engine return?', '["A year run at a share of 100, the most a contractor can hold, with the excess 20 reported among the reasons", "A year run at the call''s contractorProfitSharePct, the year''s own figure set aside", "A sliding scale computed by the engine from the year''s share and its daily rate", "The first year''s share refused by name, being above 100"]'::jsonb, 3, 'The engine refuses the year''s share by name: years[0].contractorProfitSharePct must be a number from 0 to 100; got 120. A year''s own share is how a sliding scale enters the engine: "a year''s own figure carries a sliding scale, e.g. by daily rate or R-factor, computed outside". The engine computes no scale and caps no share.'),
  ('joa', 'intermediate', 'module', 'm05-psc-cost-recovery', 15, 'Discounting at 0.100000 to 2029, what NPV does the canonical npv give EKO and NOC on psc-ekene (royalty 12.5, limit 60 of gross, share 60, tax 30, opening pool 142000000.000000)?', '["EKO 53034092.139510 and NOC 26517046.069755", "EKO 95024921.509253 and NOC 49870804.456959, the NPVs of the Ekene carry", "EKO 53034092.139510 and NOC 0.000000, NOC being carried and holding no stream under a PSC", "EKO 33146307.587194 and NOC 19887784.552316, the partners taken in the order of the carry"]'::jsonb, 0, 'The engine returns EKO 53034092.139510, PA 33146307.587194, PB 19887784.552316 and NOC 26517046.069755 on the PSC variant, each an NPV at 0.100000 to 2029. The carry NPVs are of a different call with its own base year, 2027, and NOC is not carried in the PSC variant.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 1, 'The World Bank Petroleum Sector Briefing Note No. 8 (November 2007) two-barrel example states gross 100, costs 25, royalty 10 percent, a cost oil limit of 60 percent of gross, a contractor profit share of 40 percent and tax 30 percent. The note prints that the contractor retains US$43 and the government takes $57. What does the engine return?', '["The note''s 43 and 57 exactly, since the engine reproduces a published example to the cent", "43.200000 and 56.800000, which round to the note''s 43 and 57", "43.200000 and 56.800000, which shows the note is in error by 0.2 and must be corrected before it is taught", "26.000000 and 39.000000, the profit oil split alone"]'::jsonb, 1, 'The engine returns 43.200000 and 56.800000 on the note''s own terms; the note prints its totals in whole dollars, and the two engine figures round to 43 and 57. The printed figures are the text''s rounding; the note is not in error. A printed figure and an exact one are quoted side by side and are not keyed as equal. 26.000000 is the contractor''s profit oil alone, before tax and without its cost oil.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 2, 'A limit of 60 percent of gross, a royalty of 10 percent, costs of 25 and gross of 100 are the terms of World Bank Briefing Note No. 8 (November 2007). What cost oil limit and cost recovered come back?', '["60 percent of the revenue after royalty of 90, since applyPSC reads every limit on that base", "A limit of 60.000000 with 60.000000 recovered, as a limit is always taken in full", "25.000000, the costs, since a limit cannot exceed what there is to recover", "A limit of 60.000000, and 25.000000 recovered, the costs sitting below it"]'::jsonb, 3, 'The engine returns a limit of 60.000000, as the note prints ("60 percent of the gross revenue or US$60"), and, as with the Ekene variant, the engine passes a limit stated on gross to the canonical applyPSC as a fraction of revenue after royalty. The engine keeps no copy of applyPSC of its own. The cost recovered is 25.000000, below the limit of 60.000000; the limit is a ceiling.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 3, 'In the World Bank Note 8 (November 2007) two-barrel case (gross 100, royalty 10 percent) the costs of 25 are recovered in full; the contractor''s profit share is 40 percent and tax 30 percent. Which contractor profit oil and income tax result?', '["Contractor profit oil 26.000000 and tax 7.800000, the taxable income of 26 being the contractor''s profit oil here", "Contractor profit oil 39.000000, the government''s 60 percent read as the contractor''s, taxed at 30 percent", "Contractor profit oil 26.000000 and tax 0.000000, since in a production sharing contract the government''s profit oil stands in for any income tax", "Contractor profit oil 65.000000, the whole profit oil taxed at 30 percent before it is split"]'::jsonb, 0, 'The note prints "The government takes 60 percent of US$65, or US$39, and the remaining US$26 goes to the contractor.", and the engine returns contractor profit oil 26.000000, government profit oil 39.000000 and income tax 7.800000. The course notes that its taxable income of 26 is the contractor''s profit oil here, because the costs are recovered in full.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 4, 'Which does World Bank Briefing Note No. 8 (November 2007) pay first in its two-barrel example, and what does the engine return for it?', '["The cost oil, up to the limit of 60 percent of gross, before any royalty is taken", "The income tax on the contractor''s share, at 30 percent, before royalty and cost oil", "The royalty, at 10 percent: 10.000000", "The profit oil split, at 60 percent to the government, before royalty is charged"]'::jsonb, 2, 'The note prints "the royalty is paid first. At 10 percent, this amounts to $10 going to the government." (World Bank Petroleum Sector Briefing Note No. 8 (November 2007)); the engine returns royalty 10.000000. The engine''s order reads "royalty = royaltyPct % of gross; cost oil limit = costOilLimitPct % of revenue after royalty (or of gross, as stated); cost recovered = min(pool + capex + opex, limit); profit oil = revenue after royalty - cost recovered".'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 5, 'IMF FARI TNM/16/01 (February 2016), Figure 5, runs one barrel at 100 with no royalty, costs at or above the limit, the limit at 50 percent of revenue after royalty, a contractor share of 40 percent and tax 30 percent. The figure prints government revenue of USD30 in profit oil and USD6 in income tax. What does the engine return?', '["Cost recovered 50.000000, with income tax on cost petroleum plus profit petroleum and no deduction", "Cost recovered 60.000000, as the figure states its limit on gross like the World Bank note", "Cost recovered 50.000000, government profit oil 30.000000, income tax 6.000000, and 36.000000 to the government", "Government profit oil 20.000000 and income tax 6.000000, the 40 percent share read as the government''s"]'::jsonb, 2, 'The engine returns cost recovered 50.000000, government profit oil 30.000000, contractor profit oil 20.000000, income tax 6.000000 and 36.000000 to the government, as Figure 5 prints. Its limit is stated on revenue after royalty. The figure''s tax base of cost plus profit petroleum less allowable deductions, with deductions assumed equal to cost recovery, leaves the contractor''s profit oil.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 6, 'IMF FARI Figure 5 says "the base for CIT is equal to cost petroleum plus profit petroleum minus allowable tax deduction" and assumes the deductions equal the cost recovery. What tax base does that leave in the one-barrel figure?', '["Only the contractor''s 20 of profit petroleum, which bears the 6", "The contractor''s cost petroleum and profit petroleum together, since deductions come after the tax", "The whole profit oil of 50, taxed at 30 percent, as the government''s share is part of the base", "Nothing, since the deductions assumed equal to cost recovery wipe out the profit petroleum as well"]'::jsonb, 0, 'Figure 5 assumes "Normal tax deductions in the tax/royalty regime are assumed to be equal to the cost recovery in the PSC.", so cost petroleum less the deduction cancels and the base is the contractor''s profit petroleum; the engine returns contractor profit oil 20.000000 and income tax 6.000000, which the figure prints as USD6.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 7, 'IMF FARI Tables 12 and 13 (February 2016) are run through the engine on psc-fari-table-12: eleven years in USD million, royalty 0.000000 percent, a ceiling of 80.000000 percent of revenue after royalty. What does the course say about the agreement?', '["It agrees exactly: every printed whole number equals the engine''s figure once the engine''s figure is rounded", "It disagrees in 2005 and 2006, where the tables'' figures are shown to be arithmetic errors in the IMF model", "It agrees within 1.560000 on every line, the tolerance being applied to the ceiling and the pool as well", "It agrees at the printed precision: the largest cost line difference is 1.000000, inside the 1.5 three printed whole numbers can carry"]'::jsonb, 3, 'The course states the largest difference on a cost line (ceiling, cost petroleum, closing balance, profit) is 1.000000, inside the 1.5 a line made of at most three printed whole numbers can carry. The tables print whole numbers of an unrounded model, so the check is within the printed precision. 1.560000 is the largest difference on the profit split, and it has its own bound.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 8, 'On psc-fari-table-12, how does the engine take each year''s contractor share of profit petroleum, which IMF FARI sets by a daily-rate scale?', '["By computing the daily-rate scale of Table 11 inside the engine from each year''s production", "As a stated contractorProfitSharePct for each year, read from Table 13''s government share", "As one contractorProfitSharePct for the whole run, the average of Table 13''s shares", "By applying the Ekene variant''s 60 percent to every year of the IMF schedule"]'::jsonb, 1, 'The golden input states each year''s contractor share as contractorProfitSharePct, read from Table 13''s government share, "a daily-rate scale the tables compute outside this engine". The engine''s basis reads "contractorProfitSharePct applies to every year that does not state its own (a year''s own figure carries a sliding scale, e.g. by daily rate or R-factor, computed outside)".'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 9, 'For 2003, with no royalty and a ceiling at 80 percent of revenue after royalty, IMF FARI Tables 12 and 13 print a ceiling of 170 and cost petroleum of 170. What does the engine return?', '["A ceiling of 170.400000 and cost recovered of 170.400000", "A ceiling of 170, rounded to the table", "A ceiling of 433.600000, the 2004 figure", "A ceiling of 170.400000 with cost recovered of 250.000000, the whole pool carried in"]'::jsonb, 0, 'The engine returns 170.400000 for both the ceiling and cost recovered in 2003, where the tables print 170 of an unrounded model. The ceiling binds in the third year, so cost recovered stops at it and the pool closes at 298.600000, printed as 299. The engine rounds nothing to the printed precision.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 10, 'Before production starts, what do 2001 and 2002 of the FARI Table 12 run show (no royalty, an 80 percent ceiling on revenue after royalty)?', '["A cost recovery of 250 in 2001, spent before production and recovered at once", "No cost recovered, and a pool of 250.000000 carried through both years", "A pool of 250 written off at the end of 2002", "A ceiling of 250 each year, the pool setting its own limit before production starts"]'::jsonb, 1, 'The engine returns a ceiling of 0.000000, cost recovered 0.000000 and a pool out of 250.000000 in 2001 and 2002, where the tables print 0, 0 and 250. The course states: "The pool of 250 carried forward through the first two years and the ceilings that bind in the third and fourth are reproduced." A pool is carried; nothing is written off.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 11, 'What does the engine''s validation record conclude from the IMF schedule, in its own words?', '["A defect in applyPSC''s limit, corrected so that the schedule''s whole numbers are matched in every year", "Agreement on the profit split only, the cost pool being checked against the World Bank note alone", "Result: NO DEFECT, the applyPSC cost pool arithmetic reproducing the IMF schedule year by year", "A mismatch in 2005, left open for the reader to settle"]'::jsonb, 2, 'The validation record reads: "Result: NO DEFECT. The cost pool arithmetic of `applyPSC` (royalty on gross; the limit on revenue after royalty; cost recovered = min(pool + capex + opex, limit); the rest carried; profit oil = revenue after royalty - cost recovered) reproduces the IMF schedule year by year". The course teaches no repair history, and the agreement covers both the cost lines and the profit split within their stated bounds.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 12, 'Which edition of the IMF FARI methodology does the course read its Figure 5 and Tables 12 and 13 from, and how was it read?', '["WP/24/89, April 2024, read from the live IMF site on 2026-09-26, the direct download being open", "TNM/16/01, February 2016, a licensed text taught by concept only and never quoted", "Briefing Note No. 8, November 2007, which the IMF republished with FARI''s tables", "TNM/16/01, February 2016, read on 2026-09-26 from the Wayback capture of 12 October 2025"]'::jsonb, 3, 'The sources table lists IMF, Luca and Mesa Puyo, FARI Methodology, TNM/16/01, February 2016, read from the Wayback capture of 12 October 2025 because the direct download answered 403, on 2026-09-26. It is a public text and is quoted with its citation. WP/24/89 is a different IMF paper, read for concepts only.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 13, 'World Bank Briefing Note No. 8 (November 2007) says: "For paying income tax, there are no limits on deductible expenses in the way there are limits on cost oil." What does the engine''s stated reading of the PSC income tax say it taxes?', '["Every cost incurred deducted from the contractor''s entitlement, as the note''s sentence requires", "The contractor''s entitlement after cost oil, the limit on cost oil being lifted for the tax", "The government''s profit oil, since the contractor''s tax is paid from the state''s share", "The contractor''s profit oil share, as FARI TNM/16/01 and World Bank Note 8 assume"]'::jsonb, 3, 'That line of the note is about deductions in general; the engine names its own choice in its basis and cites FARI TNM/16/01 and World Bank Note 8 as the two texts that assume it. The other three options each tax a different base. No tax figure the course grades rests on this choice, and in both published examples every cost is recovered, so the engine reproduces their printed tax.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 14, 'In the IMF schedule (psc-fari-table-12), the profit split differs from the printed tables by up to 1.560000. Why does the course accept that?', '["It is inside 1.5 plus half a per cent of the year''s profit petroleum, as Table 13 prints the government share as a whole per cent", "It is inside the 1.5 that any line of three printed whole numbers carries, the same bound as the cost lines", "It rounds to 2, the printed precision of the tables, and so is treated as agreement", "It is a known IMF arithmetic error of the kind OpenOil''s book prints, and is kept out of the gates"]'::jsonb, 0, 'The course states the largest difference on the profit split is 1.560000, inside 1.5 plus half a per cent of the year''s profit petroleum, because Table 13 prints the government share as a whole per cent, from which each year''s stated contractor share is read. The bound of 1.5 alone is the cost lines'' bound, and 1.560000 lies above it.'),
  ('joa', 'intermediate', 'module', 'm06-the-published-psc-checks', 15, 'IMF WP/24/89 (April 2024) says "Under a production sharing regime, revenues shared are usually net of royalties." World Bank Briefing Note No. 8 (November 2007) states its 60 percent limit on gross. What does the engine take as the limit base?', '["Revenue after royalty always, since the IMF paper describes the usual regime", "A required input, costOilLimitBase, \"after-royalty\" or \"gross\", with no default", "Gross revenue always, since a published worked example is the engine''s reference", "Whichever base gives the larger limit, the contractor''s reading of an unclear contract"]'::jsonb, 1, 'The engine takes costOilLimitBase as a required input with no default; each golden input states its example''s base, gross for the World Bank note and after-royalty for IMF FARI Figure 5. A call without it is refused by name, and the engine picks no base on the contractor''s behalf.'),
  ('joa', 'intermediate', 'final', null, 1, 'Add up what the paying parties are asked for in March 2027 on the Ekene ledger: forecast 12000000.000000, January''s 400000 over-call arriving under a two-month lag, credits carried, threshold 500000.000000.', '["12000000.000000, the whole forecast, the credit waiting for the year-end reconciliation", "11200000.000000, March''s own actual, since a call is trued up to the month''s spend", "11600000.000000", "The forecast with the credit added on top"]'::jsonb, 2, 'March''s month row prints calls of 11600000.000000 on a forecast of 12000000.000000: January''s over-call reaches March two months later and reduces each paying party''s call by its own January difference. 11200000.000000 is March''s actual, known only after the call. A credit lowers a call; it never raises it.'),
  ('joa', 'intermediate', 'final', null, 2, 'On the Ekene ledger (lag 2 months, rule "carry", threshold 500000.000000), EKO over-calls by 200000.000000 in January and under-calls by -250000.000000 in February. What balance with the operator does EKO hold at the end of February 2027?', '["-50000.000000", "200000.000000, since February''s under-call is not counted until the call it adjusts", "-250000.000000, February''s difference alone, as January''s credit was used up in February", "0.000000, the January credit and the February under-call cancelling out"]'::jsonb, 0, 'EKO''s February row prints a balance of -50000.000000: both differences are still waiting for the calls their lag names, and the balance with the operator counts the differences not yet adjusted. January''s credit is used in March, so it is still held at the end of February.'),
  ('joa', 'intermediate', 'final', null, 3, 'October 2027 on the Ekene ledger (lag 2 months, rule "carry", threshold 500000.000000) meets two things at once: August''s under-call and the credit carried from September. What does EKO''s October row show?', '["An adjustment of 100000.000000, the carried credit alone, since an under-call waits for the month after a carried credit is spent", "An adjustment of -52000.000000, August''s under-call alone, the carried credit waiting a month", "A call of 4000000.000000, the forecast share, with both items netted at the close", "An adjustment of 48000.000000 and a call of 3952000.000000 on a forecast share of 4000000.000000"]'::jsonb, 3, 'The engine applies both in October: "2027-10: the under-call of 104000 in 2027-08 (forecast 3000000, actual 3104000) is added to this cash call, 2 months later" and "2027-10: a credit of 200000 held from 2027-09 is applied to this cash call". EKO''s row prints an adjustment of 48000.000000 and a call of 3952000.000000.'),
  ('joa', 'intermediate', 'final', null, 4, 'EKO''s forecast share for December 2027 is 2500000.000000, and October''s under-call of 400000 reaches that call under the Ekene terms (lag 2, carry, threshold 500000.000000). What is EKO asked for?', '["The forecast share less the under-call, as if it were a credit", "2700000.000000 on a forecast share of 2500000.000000, its adjustment being -200000.000000", "2500000.000000, as an under-call is billed in arrears in the next month", "The whole 400000 under-call added to EKO''s call alone as operator"]'::jsonb, 1, 'An under-call adds to the call it reaches: EKO''s December row prints an adjustment of -200000.000000, its half of October''s 400000, and a call of 2700000.000000, the engine''s reason naming October''s forecast of 8000000 and actual of 8400000. Treating the under-call as a credit moves the call the wrong way, and arrears billing is only for spend made in a month with no call.'),
  ('joa', 'intermediate', 'final', null, 5, 'Three parties (A 50, B 30, C 20 percent) run cc-zero-call-month: a one-month lag, credits carried, no threshold. January over-calls by 200 and February is forecast at 0.000000. What happens in February and March?', '["February is called at 0.000000 with 200.000000 carried; March is called 200.000000 on a forecast of 400.000000", "February makes no call, its forecast being 0; January''s credit waits and March is called 400.000000", "February is called -200.000000, the credit refunded; March is called 400.000000", "February and March are each called 0.000000"]'::jsonb, 0, 'With no threshold, February is called: "2027-02: a forecast of 0: the cash call is the adjustment alone", and under "carry" the credit waits ("the call is 0 and the rest of the credit is carried to the next cash call"). March applies it: "2027-03: a credit of 200 held from 2027-02 is applied to this cash call". A negative call of -200.000000 is the "refund" rule''s answer.'),
  ('joa', 'intermediate', 'final', null, 6, 'A ledger''s final month, December 2027, is forecast at just 100.000000 against a threshold of 500 (cc-last-month-uncalled, two-month lag, credits carried) and spends 120.000000. How is December treated?', '["It calls the 100.000000 anyway, since the last month of a ledger is always called to close the year", "It refuses the ledger, as its last month cannot be billed in arrears inside the months given", "It makes no call, and its reason says the actual is billed in arrears in the next month", "It adds December''s 120.000000 to November''s call"]'::jsonb, 2, 'The forecast of 100 is below the stated threshold, so December is not called: "2027-12: no cash call: the forecast 100 is below the stated threshold 500; the actual is billed in arrears in the next month". A month''s own call is never re-opened, and the last month gets no special rule.'),
  ('joa', 'intermediate', 'final', null, 7, 'A cash call ledger lists 2027-01 and then 2027-03 as its first two months. What does the engine return?', '["A ledger that treats February as a month with a zero forecast and calls only the adjustment in it", "A ledger of two months, the gap ignored, with January''s difference adjusting the March call", "A ledger in which the missing month is billed in arrears in March", "A refusal naming months[1].month, which must be 2027-02, the months being consecutive"]'::jsonb, 3, 'The engine refuses the gap, in its own words: months[1].month must be 2027-02, the month after 2027-01 (the months are consecutive); got "2027-03". It invents no missing month and skips nothing, because the lag counts calendar months.'),
  ('joa', 'intermediate', 'final', null, 8, 'The golden input carry-partial-stated states parties A 60, B 20 and N 20 percent, a compound uplift of 12.5 percent and carry recovery from 50 percent of N''s share. 2029 opens at 12.500000 with 100.000000 available. What is recovered in 2029?', '["12.500000, the opening balance, since a carried party pays no uplift on an uplift", "14.062500, the balance with its uplift of 1.562500", "100.000000, the whole amount available", "12.500000, with 1.562500 written off"]'::jsonb, 1, 'The uplift is charged on the opening balance, 12.5 percent of 12.500000 being 1.562500, and the balance of 14.062500 is less than the 100.000000 available: "2029: the balance 14.06 is recovered with 14.06 of the 100 available; the carried party receives 185.94 of its share 200". Compounding charges uplift on an uplift carried forward, and nothing is written off without a cap.'),
  ('joa', 'intermediate', 'final', null, 9, 'On the Ekene carry (compound 8.000000 percent a year on the opening balance, carry recovery from 50.000000 percent of NOC''s share, basis "contract"), 2030 is the first year NOC has entitlement. What closes 2030?', '["What is left once the whole share of 19200000.000000 is taken against the balance", "32088960.000000, the opening balance, since the carry recovery starts in the year after the first entitlement", "What is left with the uplift charged only after the year''s carry recovery is taken off", "25056076.800000, after 9600000.000000 recovered of 34656076.800000 due"]'::jsonb, 3, 'The engine''s reason reads "2030: 9600000 recovered of 34656076.8 due; 25056076.8 carried to 2031". The stated carry recovery share is 50 percent of the share of 19200000.000000, so 9600000.000000 is available, and the uplift of 2567116.800000 is charged on the opening 32088960.000000 before the year-end carry recovery.'),
  ('joa', 'intermediate', 'final', null, 10, 'Across 2027 to 2036, how much uplift does the 8.000000 percent compound Ekene carry (half of NOC''s share, basis "contract") earn in all, and how much do the carriers get back on their 28400000.000000?', '["An uplift of 14200000.000000 and 42600000.000000 recovered", "An uplift of 9529407.979520 and 25000000.000000 recovered", "An uplift of 10067760.617882 and 38467760.617882 recovered", "An uplift of 0.000000 and 28400000.000000 recovered, the Act barring any uplift on the Ekene carry"]'::jsonb, 2, 'The totals print carried cost 28400000.000000, uplift 10067760.617882, recovered 38467760.617882 and nothing written off, recovered in 2033. 14200000.000000 and 42600000.000000 are the 150 percent multiple''s totals; 9529407.979520 and 25000000.000000 are the capped carry''s. The Act''s bar on uplift applies under basis "pia-s85-4", which this carry does not state.'),
  ('joa', 'intermediate', 'final', null, 11, 'Which carrier gains from an uplift? At 0.100000 to 2027, EKO''s value is 95024921.509253 when the Ekene carry compounds at 8.000000 percent from half of NOC''s share under a contract. What is it when the carry follows s.85(4), with no uplift, from the whole share?', '["92668197.518975, lower, as EKO recovers no uplift", "95024921.509253, unchanged, since EKO''s NPV depends only on its own costs and entitlement", "96139876.399404, higher, since EKO is repaid sooner and so gains in value", "54584252.437515, the carried party''s figure"]'::jsonb, 0, 'The canonical npv returns EKO 92668197.518975 on the Act''s carry against 95024921.509253 on the compound carry: the carrier gives up the uplift. 96139876.399404 is EKO''s NPV under the 150 percent multiple. 54584252.437515 is NOC''s NPV on the Act''s carry.'),
  ('joa', 'intermediate', 'final', null, 12, 'A learner builds a carryRecovery call on the Ekene carry and leaves out the basis. What does the engine return?', '["A carry recovery under the contract basis, the Act''s basis applying only when stated", "A carry recovery under the Act, since NOC is the state participant", "A carry recovery with no basis line in its report", "Refused, the basis being a required term the engine picks for no caller"]'::jsonb, 3, 'The basis is a required term: the engine refuses a call without it and chooses neither basis for the caller. Only the stated basis "pia-s85-4" brings in the Act''s bar on uplift; a party''s name brings in nothing.'),
  ('joa', 'intermediate', 'final', null, 13, 'In the first year of NOC''s entitlement after its back-in to 40 percent under the Act (half its new share available), how much of the refund of 98000000.000000 is paid back, and what is left?', '["38400000.000000 recovered, the whole new share, as the Act takes the refund from future production", "19200000.000000 recovered of NOC''s share of 38400000.000000, and 78800000.000000 carried to 2031", "9600000.000000 recovered, half of NOC''s old 20 percent share", "Nothing recovered until 2031, a year after participation"]'::jsonb, 1, 'The engine''s reason reads "2030: 19200000 recovered of 98000000 due; 78800000 carried to 2031"; NOC''s new share of 38400000.000000 makes 19200000.000000 available at the stated 50 percent, and NOC receives the other 19200000.000000. The refund recovery reads the new share after the back-in.'),
  ('joa', 'intermediate', 'final', null, 14, 'On backin-pia-at-60 NOC backs in from 20 to 60 percent under basis "pia-s85-4". What does EKO hold after it, and what refund does it receive?', '["0.000000, EKO ceding all 40 points as operator, and a refund of 196000000.000000", "30.000000, as in the back-in to 40, and a refund of 49000000.000000", "20.000000, and no refund, since at the ceiling the Act refunds nothing", "20.000000, keeping 40 / 80 of its 40, and a refund of 98000000.000000"]'::jsonb, 3, 'The engine''s reason reads "NOC backs in from 20% to 60%: the others keep 40 / 80 of their interests; refund 40% x refundable costs 490000000 = 196000000 (156000000 excluded)"; its table prints EKO after 20.000000 and a refund received of 98000000.000000, in proportion to the 20.000000 points EKO gives up.'),
  ('joa', 'intermediate', 'final', null, 15, 'On backin-ekene-contract-upfront (basis "contract", refundable kinds stated to include exploration), what reason does the engine give for the signature bonus of 10000000.000000?', '["It is not refundable, being not a stated refundable kind", "It is not refundable under PIA s.85(4)(c), the Act''s list applying to every back-in", "It is refundable, a bonus being a proven cost of the licence", "It is refundable at 20 percent, NOC''s change of participating interest"]'::jsonb, 0, 'Under a contract basis the reason reads "signature bonus: 10000000 (bonus) is not refundable (not a stated refundable kind)". The same line under the Act reads the s.85(4)(c) citation. The basis decides which list applies.'),
  ('joa', 'intermediate', 'final', null, 16, 'Under basis "contract", a learner forgets to list which cost kinds may be refunded. What comes back?', '["A back-in using the Act''s development and production list", "A back-in in which every cost line is refundable", "A refusal: under a contract the refundable kinds must be stated, with no default", "A back-in in which no line is refundable, the refund being 0.000000"]'::jsonb, 2, 'The engine''s message reads: refundableKinds must be an array of cost kinds stated under basis "contract" (exploration, development, production, bonus, penalty, interest, premium, markup; no default); got nothing. The Act''s list is used only under "pia-s85-4", and a contract''s list is never guessed.'),
  ('joa', 'intermediate', 'final', null, 17, 'Paid in one sum on entry (refundForm "upfront", basis "contract"), a refund is typed together with a list of future years. What comes back?', '["An upfront refund, with the years serving to discount it", "A refusal naming years, which must be left out when the refund is paid upfront", "A refund recovered from the stated years, the upfront form set aside", "A refusal naming refundForm, since an upfront refund is barred on every basis"]'::jsonb, 1, 'The engine refuses the extra term: years must be left out when refundForm is "upfront". An upfront refund has no refund recovery ledger. The bar on an upfront refund is the Act''s and applies under "pia-s85-4"; the contract-basis case backin-ekene-contract-upfront returns a refund of 125200000.000000.'),
  ('joa', 'intermediate', 'final', null, 18, 'Suppose PB never cures its Ekene default and the call is read at 2027-07-01, with simple default interest at 8.250000 percent on 360 days and no grace. What does the engine charge?', '["55569.791577 on 4 whole months, the method switching to monthly once a month has passed", "20625.000000, the default interest stopping at the cure date the fixture states", "56718.750000, the default interest received by EKO when it covers two defaulters", "55916.666667 on 122 days"]'::jsonb, 3, 'The engine''s reason reads "interest 2000000 x 8.25% x 122 days / 360 = 55916.67 (from 2027-03-01 to asOf 2027-07-01, the default still open, the last date excluded)". 55569.791577 is the monthly-compound case; the method is a stated term. An open default runs to asOf.'),
  ('joa', 'intermediate', 'final', null, 19, 'On default-monthly-compound-uncured PB''s 2000000.000000 is still unpaid four months after its due date, at 8.25 percent compounded monthly on 360 days with a 72-hour grace. What is charged?', '["55569.791577, on 4 whole months and 0 days", "55916.666667 on 122 days", "0.000000, the 72-hour grace suspending default interest while a default is open", "56718.750000, compounding the four months and the 72 hours of grace on top"]'::jsonb, 0, 'The reason prints "interest 2000000 x ((1 + 8.25% / 12)^4 x (1 + 8.25% x 0 days / 360) - 1), 4 whole months and 0 days = 55569.79". 55916.666667 is the simple figure on the same days. The 72 hours are long past, and under its stated grace the engine then counts from the due date itself.'),
  ('joa', 'intermediate', 'final', null, 20, 'On default-monthly-compound-whole-months PB (2000000.000000 unpaid, 8.250000 percent, monthly-compound, 360-day basis, grace 0 hours) cures on 2027-05-01, due 2027-03-01. What does the engine count?', '["61 days simple, the month count being used only for defaults still open", "1 whole month and 30 remaining days", "27594.531250: two whole months, no days left over", "2 whole months and 1 remaining day, the cure date counted in"]'::jsonb, 2, 'A cure on a month anniversary gives whole months only: "interest 2000000 x ((1 + 8.25% / 12)^2 x (1 + 8.25% x 0 days / 360) - 1), 2 whole months and 0 days = 27594.53". The cure date is excluded, and months keep the day of the month.'),
  ('joa', 'intermediate', 'final', null, 21, 'On default-monthly-compound-month-end party C owes 200000.000000 from 2027-01-31, open at asOf 2027-04-15, at 12 percent, monthly-compound, 365-day basis, grace 0 hours. How does the engine count the time?', '["74 days simple on a 365-day year", "2 whole months and then 15 days, giving 5026.126027", "2 whole months ending 2027-03-28, February''s last day kept as the day of the month, then the rest as days", "3 whole months, the part-month rounded up"]'::jsonb, 1, 'The reason prints "interest 200000 x ((1 + 12% / 12)^2 x (1 + 12% x 15 days / 365) - 1), 2 whole months and 15 days = 5026.13"; the field is 5026.126027. A month from a month end keeps the day of the month, the last day when the month is shorter.'),
  ('joa', 'intermediate', 'final', null, 22, 'PB''s Ekene default earns 20625.000000 of default interest (8.250000 percent, simple, 360-day basis, grace 0 hours, cured 2027-04-15). How does the engine share it, as it states its cover?', '["EKO and PA in equal halves, each having advanced part of the cover", "EKO alone, as the operator that administers the joint account", "EKO, PA and NOC by participating interest", "EKO 12692.307692 and PA 7932.692308, in proportion to their cover"]'::jsonb, 3, 'The engine''s basis reads "distributed to the parties financing the default in proportion to their cover", and the table prints EKO 12692.307692 and PA 7932.692308. NOC, carried, advances none of the cover and receives none of the default interest.'),
  ('joa', 'intermediate', 'final', null, 23, 'Party C''s default on default-working-days-holiday states suspension after 5 working-days from 2027-12-22, with stated holidays on 2027-12-24, 2027-12-27, 2027-12-28 and 2028-01-01. When does the engine put the trigger?', '["After 2028-01-03, working days being Monday to Friday less the stated holidays", "After five calendar days, the weekend and the holidays counted like any other day", "After the fifth weekday, the stated holidays ignored since the engine keeps no calendar of them", "After 2028-01-05, the asOf date, since a suspension waits for the date the call is read at"]'::jsonb, 0, 'The engine''s reason reads "the suspension of its rights (as the contract states) starts after 5 working days from 2027-12-22, that is after 2028-01-03: triggered, the default being open after 2028-01-03". A weekend and the stated holidays fall inside the count.'),
  ('joa', 'intermediate', 'final', null, 24, 'PB''s Ekene default states forfeiture after 3 months from 2027-03-10, a trigger date of 2027-06-10. The default is still open at asOf 2027-06-10 on one golden input and at asOf 2027-06-11 on another. What does the engine report?', '["Triggered on both, as the default is open on the trigger date itself", "Not triggered on either, forfeiture needing a fourth month", "Not triggered at 2027-06-10; triggered at 2027-06-11", "Triggered at 2027-06-10 and reported with the compensation computed"]'::jsonb, 2, 'A consequence applies when the default is open after the whole trigger date: the first reads "not triggered, the default being open only to asOf 2027-06-10", the second "triggered, the default being open after 2027-06-10". The compensation on an assignment is reported only; the engine computes none.'),
  ('joa', 'intermediate', 'final', null, 25, 'A contract''s default interest states a day basis of 366. What does the engine return?', '["Default interest on a 366-day year, the stated basis being used as given", "A refusal: interest.dayBasis must be 365 or 360; got 366", "Default interest on a 365-day year, the nearest basis the engine accepts", "Default interest on a 360-day year, the Norwegian agreement''s basis"]'::jsonb, 1, 'The engine accepts 365 or 360 and refuses anything else by name. It rounds no basis to the nearest accepted one, and the day basis is a stated term with no default.'),
  ('joa', 'intermediate', 'final', null, 26, 'Read the 2031 row of the Ekene PSC variant: royalty 12.5, a cost oil limit of 60 on gross, contractor share 60, tax 30, opening pool 142000000.000000. What royalty, cost recovered and profit oil does it hold?', '["Royalty 24637500.000000, with only the year''s capex and opex recovered and the pool carried in left alone", "Royalty 27375000.000000, cost recovered 131400000.000000 and profit oil 60225000.000000", "Royalty 24637500.000000, cost recovered 103477500.000000 and profit oil 68985000.000000", "Royalty 24637500.000000, cost recovered 118260000.000000 and profit oil 54202500.000000"]'::jsonb, 3, 'The 2031 row prints royalty 24637500.000000, cost recovered 118260000.000000 (the limit binds, the pool carried in being 400600000.000000) and profit oil 54202500.000000. The 2030 figures are 27375000.000000, 131400000.000000 and 60225000.000000. 103477500.000000 and 68985000.000000 are 2031 on the after-royalty base.'),
  ('joa', 'intermediate', 'final', null, 27, 'Add up the government''s take over the ten years of the Ekene PSC variant, whose terms are a 12.5 percent royalty, cost oil capped at 60 percent of gross, a 60 percent contractor share, 30 percent tax and 142000000.000000 of opening pool. How much is it, and how much of it is tax?', '["Government take 420489742.500000, of which tax 78453967.500000", "Government take 174342150.000000, its profit oil alone, with tax counted to the contractor", "Government take 78453967.500000, the tax alone", "Government take 921059257.500000"]'::jsonb, 0, 'The totals print government profit oil 174342150.000000, tax 78453967.500000, contractor entitlement 921059257.500000 and government take 420489742.500000. The government take counts more than its profit oil, and 921059257.500000 is the contractor''s entitlement.'),
  ('joa', 'intermediate', 'final', null, 28, 'By 2038 the Ekene variant''s pool is gone and opex is 28000000.000000 (a limit of 60 on gross after a 12.5 royalty). What is recovered, and against what limit?', '["56563200.000000 recovered, the whole limit, the excess going to the contractor as cost oil", "0.000000 recovered, since cost recovery ends when the pool is cleared", "28000000.000000 recovered against a limit of 56563200.000000", "49492800.000000 recovered, the limit binding"]'::jsonb, 2, 'The 2038 row prints cost recovered 28000000.000000 and a limit of 56563200.000000: cost recovered is the lesser of what is recoverable and the limit. Opex stays recoverable after the pool is cleared. 49492800.000000 is the 2038 limit on the after-royalty base.'),
  ('joa', 'intermediate', 'final', null, 29, 'A 60.000000 percent limit is tried on both bases for 2030 of the Ekene PSC variant (12.5 royalty, 60 share, 30 tax, 142000000.000000 carried in). How much profit oil is left on each?', '["76650000.000000 on gross and 60225000.000000 on revenue after royalty", "Profit oil of 60225000.000000 with the gross limit, 76650000.000000 with the after-royalty one", "60225000.000000 on both, the base changing only the pool", "191625000.000000 on both, the revenue after royalty"]'::jsonb, 1, 'On gross the limit of 131400000.000000 recovers more cost and leaves profit oil of 60225000.000000; on revenue after royalty the smaller limit of 114975000.000000 leaves 76650000.000000. The base moves the limit and so the split.'),
  ('joa', 'intermediate', 'final', null, 30, 'A learner types costRecoveryLimitPct in place of the engine''s term for the limit. What does the engine return?', '["A PSC run that reads the unknown key as costOilLimitPct, the nearest term the engine accepts, and says so in a reason", "A PSC run with no limit, the unknown key dropped", "A refusal naming costOilLimitPct as missing", "Refused by name as a key the engine does not read, with its accepted keys listed"]'::jsonb, 3, 'The engine refuses the key it does not read and lists the accepted keys: years, royaltyPct, costOilLimitPct, costOilLimitBase, contractorProfitSharePct, taxRatePct, openingCostPool, parties, discountRate, baseYear. It maps no key onto another and drops nothing silently.'),
  ('joa', 'intermediate', 'final', null, 31, 'PIA 2021 s.311(2)(a)(iii) sets a cost oil limit of not more than 60 percent for a renegotiated PSC. What does the engine do with that figure?', '["It reports it in the basis only; the limit applied is the contract''s stated figure", "It caps every stated costOilLimitPct at 60, the Act''s ceiling for a renegotiated contract", "It applies 60 percent of gross as the limit whenever a PSC call leaves the cost oil limit unstated", "It refuses any limit above 60 under basis \"pia-s85-4\", as it refuses a back-in above 60"]'::jsonb, 0, 'The engine''s basis reads "PIA s.311(2)(a)(iii): a renegotiated production sharing contract features a cost oil limit of not more than 60% of the total oil production; the limit here is the contract''s stated figure", and PIA_JV.renegotiatedPscCostOilLimitPct is reported in the basis only. The limit is a required input.'),
  ('joa', 'intermediate', 'final', null, 32, 'Divide the one-barrel profit oil of IMF FARI TNM/16/01 (February 2016) Figure 5 as the engine does: the contractor holds 40 percent of it, cost oil is capped at half of what royalty leaves, tax is 30 percent, there is no royalty, costs reach the cap, and the barrel sells for 100. Who gets what?', '["Contractor 30.000000 and government 20.000000", "Contractor 26.000000 and government 39.000000", "Contractor 20.000000 and government 30.000000", "Contractor 20.000000 and government 36.000000"]'::jsonb, 2, 'The engine returns contractor profit oil 20.000000 and government profit oil 30.000000, as the figure prints. 26.000000 and 39.000000 are the World Bank note''s split, and 36.000000 is the government''s profit oil and tax together.'),
  ('joa', 'intermediate', 'final', null, 33, 'In 2008 of the IMF schedule (psc-fari-table-12), Table 13 prints the contractor''s profit petroleum as 181. What does the engine return, and how does the course read the gap?', '["181, the engine matching the printed figure once its own figure is rounded to the whole number the table prints", "182.000000, one more than printed, and within the bound the course sets for the profit split", "182.000000, a gap the validation record reports as a defect in applyPSC and leaves open for the reader to settle", "A share one lower, the engine truncating it"]'::jsonb, 1, 'The engine returns 182.000000 where Table 13 prints 181. The course bounds the split more widely than the cost lines, since the tables print the government''s share to a whole per cent, and every year of the schedule falls inside that wider bound. Nothing is rounded to match a table, and the record finds no defect.'),
  ('joa', 'intermediate', 'final', null, 34, 'OpenOil, Oil Contracts: How to read and understand them (version 1, November 2012) prints "This is calculated by: 0.25 x 49 = 11.75 million dollars". How does the course use the book?', '["It uses the example as a golden check of the engine''s PSC tax", "It quotes the book''s 11.75 as its result", "It is a licensed text, taught by concept only", "It uses no schedule from it and teaches its state participation example as a printed arithmetic error"]'::jsonb, 3, 'The sources table records OpenOil, version 1, November 2012, Creative Commons: no schedule is used, and its state participation example is taught as a printed arithmetic error. A figure copied from a reference text is checked before it is taught.'),
  ('joa', 'intermediate', 'final', null, 35, 'NOC is carried in full on the Ekene joint venture. Reading the 2027 cash call ledger (lag 2, "carry", threshold 500000.000000) and the compound carry together, what happens to NOC''s cost share in 2027?', '["NOC is called 0.000000 every month, and its carried cost of 16400000.000000 opens its carry balance", "NOC is called 20 percent of each forecast and the carriers repay it at the year end", "NOC is called nothing and owes nothing, the carry being a gift of its cost share", "NOC''s share is billed in arrears in December and the carry covers it"]'::jsonb, 0, 'Every NOC row of the ledger prints a call of 0.000000 on a paying interest of 0.000000, and the carry ledger''s 2027 row carries NOC''s cost of 16400000.000000 to 2028, to be recovered from NOC''s share of entitlement from 2030. A carry is financing to be recovered.'),
  ('joa', 'intermediate', 'final', null, 36, 'Both the Ekene carry under the Act (carry-ekene-pia, carry recovery from 100.000000 percent of the share) and the Ekene back-in (backin-ekene-pia, refund from 50.000000 percent of NOC''s new share) state basis "pia-s85-4". What do they share, and when does each close?', '["Both carry the Act''s uplift; the carry closes in 2033 and the refund in 2031", "Neither carries an uplift; both close in 2031", "Neither carries an uplift; the carry is recovered in 2031 and the refund in 2034", "Both take the whole share; both close in 2034"]'::jsonb, 2, 'Under "pia-s85-4" the carry''s uplift must be none (s.85(4)(c)) and the refund is "recovered with no uplift". The carry is recovered in 2031 and the refund in 2034, each on its own balance and stated share.'),
  ('joa', 'intermediate', 'final', null, 37, 'Which of these contract terms may a call leave out and still get a result?', '["The reconciliation lag of a cash call ledger", "The cash call threshold, noCallBelow", "The uplift of a carry recovery", "The grace hours of default interest"]'::jsonb, 1, 'cc-ekene-2027-every-month runs with no threshold and returns calls of 69052000.000000. The lag, the uplift and the grace are required terms with no default, each refused by name when missing ("reconciliationLagMonths must be an integer at or above 1; got nothing").'),
  ('joa', 'intermediate', 'final', null, 38, 'The engine cites the Act for both a back-in and PSC cost recovery. Which provisions does each call''s basis cite?', '["Both cite s.85(4), the carried interest provision", "backIn cites s.311(2)(a)(iii); pscCostRecovery cites s.85(4)", "Neither cites the Act, both citing the Norwegian agreement", "backIn cites PIA s.85(4); pscCostRecovery cites s.85(2)(a) and s.311(2)(a)(iii) with applyPSC"]'::jsonb, 3, 'The engine''s basis.source for backIn reads the Petroleum Industry Act 2021 (Act No. 6), Official Gazette No. 142, Vol. 108, 27 August 2021 s.85(4); for pscCostRecovery it adds s.85(2)(a) and s.311(2)(a)(iii) and engines/economics/cashflow.ts applyPSC. Section 85(4) governs the concession agreement of s.85(2)(d).'),
  ('joa', 'intermediate', 'final', null, 39, 'The Kenya Model PSC 2015, Participation Agreement, is quoted in the cash call module and the default module. Which of its figures does the engine hold?', '["None: its rate and grace are stated inputs and no refund timing is held; the golden input states the 72 hours", "The 72-hour grace of Art. 6.7, which the engine applies whenever a contract states no grace of its own", "The margin over LIBOR that Art. 6.7 prints, which the engine adds to every stated default interest rate", "The fifteen-day refund of an excess advance"]'::jsonb, 0, 'Every contractual rate, grace and rule is a stated input with no default. The Kenya case states its grace ("rate and grace stated here"), and the model leaves the margin over LIBOR blank. A missing grace is refused by name.'),
  ('joa', 'intermediate', 'final', null, 40, 'On the Ekene joint venture, cash calls and the PSC variant split costs between the same four partners. Does each split on paying or on participating interests, and what does NOC bear?', '["Both use paying interests, so NOC pays nothing in either", "Both use participating interests, so NOC pays 20 percent in both", "Cash calls use paying interests (NOC 0.000000); the PSC splits by participating interest (NOC -56000000.000000 of the 2029 capex)", "Cash calls use participating interests; the PSC uses paying interests"]'::jsonb, 2, 'Cash calls split on paying interests through calculatePartnerCosts, where NOC carried pays 0.000000. The PSC variant states no carry and splits by participating interest, so NOC''s 2029 net is -56000000.000000.'),
  ('joa', 'intermediate', 'final', null, 41, 'The engine''s reasons say "400600000 carried to 2031" on the PSC and "16400000 carried to 2028" on the carry ledger. Under the course''s vocabulary, what is a "carry"?', '["Any amount moved to a later period, the PSC cost pool and a credit held from a cash call both included", "A carried party''s cost share paid by its carriers; a pool or balance is \"carried to\" a named period", "The PSC cost pool, recovered from cost oil", "The uplift on a carried balance"]'::jsonb, 1, 'The course legislates: a carry is a carried party''s cost share paid by its carriers, and a pool, a credit or a balance moved to a later period is carried forward, or carried to a named period. The PSC pool is carried to 2031; NOC''s carry is a cost share.'),
  ('joa', 'intermediate', 'final', null, 42, 'In 2030 NOC''s carry recovery (Ekene compound carry) and its back-in refund recovery (Ekene back-in to 40 percent) each read NOC''s share of entitlement. Which share does each read?', '["19200000.000000 for both", "38400000.000000 for both, the back-in applying to the carry as well", "9600000.000000 and 19200000.000000", "19200000.000000 for the carry, on NOC''s 20 percent, and 38400000.000000 for the refund, on its new 40 percent"]'::jsonb, 3, 'The carry ledger''s 2030 share is 19200000.000000 on NOC''s beneficial interest of 20.000000; the back-in''s 2030 share is 38400000.000000 on NOC''s new 40 percent. 9600000.000000 and 19200000.000000 are the amounts available at 50 percent of each.');
