-- ============================================================================
-- EC9 PROFESSIONAL DEEP SEED: Joint Ventures, Operating Agreements & Cost
-- Recovery, intermediate tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, and the question rows from the
-- committed bank JSONs under tools/course-banks/joa/intermediate.
--
-- What this tier owns: RECOVERY, DEFAULT AND COST RECOVERY. The cash call
-- ledger with the reconciliation lag and a negative call refunded or carried;
-- carries with a compound or multiple uplift and a cap; the back-in of PIA
-- 2021 s.85(4); a default with pro rata cover, simple or monthly-compound
-- interest, grace, suspension and forfeiture; PSC cost recovery through the
-- canonical applyPSC and the three published checks.
--
-- AN ENGINE COURSE. There is no Suite app: the practicals run in the course's
-- own recovery calculator. The capstone grades six values of this tier, each
-- identical under every reading the engine states.
-- ============================================================================

values ('joa', 'intermediate', '{"modules":[{"key":"m01-the-cash-call-ledger","title":"The Cash Call Ledger","lesson_keys":["l01-reconciliation-carried-to-a-later-call","l02-the-reconciliation-lag","l03-a-negative-call-refunded-or-carried","l04-the-balance-with-the-operator"]},{"key":"m02-carries-with-uplift-and-caps","title":"Carries with Uplift and Caps","lesson_keys":["l01-a-carry-and-its-recovery","l02-recovery-from-the-carried-share","l03-compound-uplift-on-the-opening-balance","l04-a-multiple-uplift","l05-a-cap-and-the-write-off"]},{"key":"m03-back-in-under-the-act","title":"Back-In under the Act","lesson_keys":["l01-the-carried-interest-provision","l02-interests-after-a-back-in","l03-refundable-costs-and-exclusions","l04-the-refund-from-future-entitlement"]},{"key":"m04-default-cover-and-interest","title":"Default Cover and Interest","lesson_keys":["l01-a-default-on-a-cash-call","l02-pro-rata-cover","l03-simple-default-interest","l04-monthly-compounding-and-grace","l05-suspension-and-forfeiture"]},{"key":"m05-psc-cost-recovery","title":"PSC Cost Recovery","lesson_keys":["l01-cost-oil-profit-oil-and-the-order","l02-the-cost-oil-limit-and-its-base","l03-the-pool-carried-forward","l04-splitting-the-contractor-entitlement"]},{"key":"m06-the-published-psc-checks","title":"The Published PSC Checks","lesson_keys":["l01-the-world-bank-two-barrel-example","l02-the-imf-one-barrel-figure","l03-the-imf-schedule-year-by-year","l04-the-capstone-brief"]}]}'::jsonb, 1)
